Object.assign(window.TEM8_DICTIONARY, {"metaphor":{"media":{"uk":"media/uk/metaphor__gb_1.mp3","us":"media/us/metaphor__us_1.mp3"},"oxford":{"phon":"ˈmetəfə(r)","pos":"noun","senses":[{"en":"a word or phrase used to describe somebody/something else, in a way that is different from its normal use, in order to show that the two things have the same qualities and to make the description more powerful, for example She has a heart of stone; the use of such words and phrases","cn":"暗喻；隐喻","lab":"US English","ex":{"en":"a game of football used as a metaphor for the competitive struggle of life","cn":"用来喻指生活中的激烈斗争的一场足球比赛"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"隐喻;暗喻;比喻的说法","en":"A metaphor is an imaginative way of describing something by referring to something else which is the same in a particular way. For example, if you want to say that someone is very shy and frightened of things, you might say that they are a mouse.","ex":{"en":"...the avoidance of 'violent expressions and metaphors' like 'kill two birds with one stone'.","cn":"避免使用“有暴力意味的表达和隐喻”，例如“一石二鸟”"}},{"pos":"N-VAR 可变名词","cn":"象征;标志","en":"If one thing is a metaphor for another, it is intended or regarded as a symbol of it.","ex":{"en":"The divided family remains a powerful metaphor for a society that continued to tear itself apart.","cn":"破碎的家庭仍旧是一个继续分崩离析的社会的有力象征。"}},{"pos":"PHRASE 短语","cn":"混合(使用)隐喻(指同时运用两个矛盾的隐喻)","en":"If you mix your metaphors, you use two conflicting metaphors. People do this accidentally, or sometimes deliberately as a joke.","ex":{"en":"To mix yet more metaphors, you were trying to run before you could walk, and I've clipped your wings","cn":"混用更多的隐喻来说，你还没学会走就想跑，而我又剪掉了你的翅膀。"}}]},"examples":[{"en":"a game of football used as a metaphor for the competitive struggle of life","cn":"用来喻指生活中的激烈斗争的一场足球比赛"},{"en":"the writer's striking use of metaphor","cn":"这位作家对于隐喻的独到运用"}]},"merely":{"media":{"uk":"media/uk/merely__gb_1.mp3","us":"media/us/merely__us_1.mp3"},"oxford":{"phon":"ˈmɪəli","pos":"adverb","senses":[{"en":"used meaning ‘only’ or ‘simply’ to emphasize a fact or something that you are saying","cn":"仅仅；只不过","ex":{"en":"It is not merely a job, but a way of life.","cn":"这不仅仅是一份工作，而且是一种生活方式。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"只不过;仅仅","en":"You use merely to emphasize that something is only what you say and not better, more important, or more exciting.","ex":{"en":"Michael is now merely a good friend","cn":"迈克尔现在仅仅是个不错的朋友而已。"}},{"pos":"ADV 副词","cn":"只不过，仅仅(用于强调数量之小)","en":"You use merely to emphasize that a particular amount or quantity is very small.","ex":{"en":"The brain accounts for merely three per cent of body weight.","cn":"大脑仅占体重的3%。"}},{"pos":"PHRASE 短语","cn":"不仅仅","en":"You use not merely before the less important of two contrasting statements, as a way of emphasizing the more important statement.","ex":{"en":"The team needs players who want to play cricket for England, not merely any country that will have them","cn":"球队需要的是想为英格兰而战的板球选手，而不是愿为任何国家打球的选手。"}}]},"examples":[{"en":"It is not merely a job, but a way of life.","cn":"这不仅仅是一份工作，而且是一种生活方式。"},{"en":"They agreed to go merely because they were getting paid for it.","cn":"他们同意去只是因为他们会得到酬劳。"}]},"mes":{"oxford":{"phon":"mi","pos":"pronoun","senses":[{"en":"the form of I that is used when the speaker or writer is the object of a verb or preposition, or after the verb be （I","cn":"的宾格）我"},{"en":"( music","cn":"音 ) the third note of a major scale 大调音阶的第 3 音"}]},"media":{"uk":"media/uk/me__gb_1.mp3","us":"media/us/me__us_1.mp3"}},"mexican":{"media":{"uk":"media/uk/mexican__gb_1.mp3","us":"media/us/mexican__us_1.mp3"},"oxford":{"phon":"ˈmeksɪkən","pos":"adjective","senses":[{"en":"from or connected with Mexico","cn":"墨西哥的"},{"en":"a person from Mexico","cn":"墨西哥人","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"墨西哥的;墨西哥人的；墨西哥文化的","en":"Mexican means belonging or relating to Mexico, or to its people or culture.","ex":{"en":"...the Mexican border town of Tijuana.","cn":"墨西哥边境的蒂华纳小镇"}},{"pos":"N-COUNT 可数名词","cn":"墨西哥人;墨西哥公民;有墨西哥血统的人","en":"A Mexican is a Mexican citizen, or a person of Mexican origin.","ex":{"en":"He went down the bar to a group of Mexicans and talked to them in a low voice.","cn":"他走到酒吧里的一群墨西哥人那里，跟他们小声交谈起来。"}}]},"examples":[{"en":"the Mexican government","cn":"墨西哥政府"},{"en":"the Mexican border","cn":"墨西哥边界"}]},"mechanical":{"media":{"uk":"media/uk/mechanical__gb_1.mp3","us":"media/us/mechanical__us_1.mp3"},"oxford":{"phon":"məˈkænɪkl","pos":"adjective","senses":[{"en":"operated by power from an engine","cn":"机动的；机械驱动的；机械的","ex":{"en":"a mechanical device/toy/clock","cn":"机械装置／玩具／钟表"}},{"en":"relating to machines and engines","cn":"机器的；机械的；发动机的","ex":{"en":"mechanical problems/defects","cn":"机械问题／缺陷"}},{"en":"done without thinking, like a machine","cn":"机械般的；呆头呆脑的；无思想的","lab":"often disapproving","ex":{"en":"a mechanical gesture/response","cn":"机械的手势／回答"}},{"en":"connected with the physical laws of movement and cause and effect (= with mechanics)","cn":"机械的；机械学的","ex":{"en":"mechanical processes","cn":"机械过程"}},{"en":"good at understanding how machines work","cn":"擅长于机械原理的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"机械的;机动的","en":"A mechanical device has parts that move when it is working, often using power from an engine or from electricity.","ex":{"en":"...a small mechanical device that taps out the numbers.","cn":"能够输出数字的小型机械装置"}},{"pos":"ADJ 形容词","cn":"机械方面的;机械原理的","en":"Mechanical means relating to machines and engines and the way they work.","ex":{"en":"...mechanical engineering","cn":"机械工程学"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）精通机械的;擅长于机械原理的","en":"If you describe a person as mechanical, you mean they are naturally good at understanding how machines work.","ex":{"en":"He was a very mechanical person, who knew a lot about sound","cn":"他精通机械，了解许多有关声音的知识。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为）机械的，呆板的，不动脑筋的","en":"If you describe someone's action as mechanical, you mean that they do it automatically, without thinking about it.","ex":{"en":"It is real prayer, and not mechanical repetition","cn":"这是真正的祈祷，不是机械的重复。"}}]},"examples":[{"en":"She spoke mechanically, as if thinking of something else.","cn":"她机械地说着话，彷佛在想着什么别的事情。"},{"en":"The breakdown was due to a mechanical failure.","cn":"抛锚是机械故障造成的。"}]},"men":{"media":{"uk":"media/uk/men__gb_1.mp3","us":"media/us/men__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"(man 的复数)","en":"Men is the plural of man ."}]}},"mere":{"media":{"uk":"media/uk/mere__gb_1.mp3","us":"media/us/mere__us_1.mp3"},"oxford":{"phon":"mɪə(r)","pos":"adjective","senses":[{"en":"used when you want to emphasize how small, unimportant, etc. somebody/something is","cn":"仅仅的；只不过","ex":{"en":"It took her a mere 20 minutes to win.","cn":"她只花了 20 分钟就赢了。"}},{"en":"used when you are saying that the fact that a particular thing is present in a situation is enough to have an influence on that situation","cn":"只凭…就足以","ex":{"en":"His mere presence (= just the fact that he was there) made her feel afraid.","cn":"他当时在场，这就足以让她害怕了。"}},{"en":"a small lake","cn":"小湖；池塘","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"只不过;仅仅","en":"You use mere to emphasize how unimportant or inadequate something is, in comparison to the general situation you are describing.","ex":{"en":"...successful exhibitions which go beyond mere success","cn":"不仅仅是成功而是大获成功的展览"}},{"pos":"ADJ 形容词","cn":"极小的，微不足道的，单单(表示虽小却有重要影响)","en":"You use mere to indicate that a quality or action that is usually unimportant has a very important or strong effect.","ex":{"en":"The mere mention of food had triggered off hunger pangs","cn":"单单提到食物就引起了阵阵饥饿感。"}},{"pos":"ADJ 形容词","cn":"只不过，仅仅(用于强调数量之小)","en":"You use mere to emphasize how small a particular amount or number is.","ex":{"en":"Sixty per cent of teachers are women, but a mere 5 percent of women are heads and deputies","cn":"有60%的教师是女性，但是担任校长和副校长的女性仅占5%。"}}]},"examples":[{"en":"You've got the job. The interview will be a mere formality.","cn":"你已经得到了这份工作。面试不过是个形式。"},{"en":"A mere 2% of their budget has been spent on publicity.","cn":"他们的预算开支只有 2% 用于宣传。"}]},"messenger":{"media":{"uk":"media/uk/messenger__gb_1.mp3","us":"media/us/messenger__us_1.mp3"},"oxford":{"phon":"ˈmesɪndʒə(r)","pos":"noun","senses":[{"en":"a person who gives a message to somebody or who delivers messages to people as a job","cn":"送信人；通信员；邮递员；信使","ex":{"en":"a bike/bicycle messenger","cn":"骑自行车的快递员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"送信者;通信员;信使","en":"A messenger takes a message to someone, or takes messages regularly as their job.","ex":{"en":"There will be a messenger at the Airport to collect the photographs from our courier","cn":"机场会有一名信使从我们的递送员手中取走照片。"}}]},"examples":[{"en":"He sent the order by messenger.","cn":"他通过邮递员发出订单。"},{"en":"a motorcycle messenger","cn":"骑摩托车的邮递员"}]},"meters":{"oxford":{"phon":"ˈmiːtə(r)","pos":"noun","senses":[{"en":"( especially in compounds","cn":"尤用于构成复合词 ) a device that measures and records the amount of electricity, gas, water, etc. that you have used or the time"},{"en":"( in compounds","cn":"构成复合词 ) a device for measuring the thing mentioned 计；仪；表"}]},"media":{"uk":"media/uk/meter__gb_1.mp3","us":"media/us/meter__us_1.mp3"}},"merit":{"media":{"uk":"media/uk/merit__gb_1.mp3","us":"media/us/merit__us_1.mp3"},"oxford":{"phon":"ˈmerɪt","pos":"noun","senses":[{"en":"the quality of being good and of deserving praise or reward","cn":"优秀；美德；价值","g":"[uncountable]","lab":"formal","ex":{"en":"a work of outstanding artistic merit","cn":"具有杰出艺术价值的作品"}},{"en":"a good feature that deserves praise or reward","cn":"优点；功绩；长处","g":"[countable, usually plural]","ex":{"en":"We will consider each case on its (own) merits (= without considering any other issues, feelings, etc.).","cn":"我们将根据每件事情本身的情况来考虑。"}},{"en":"a grade in an exam or for a piece of work at school or university that is very good","cn":"（学业成绩的）良好","g":"[countable]","lab":"British English"},{"en":"a special mark or award given as a reward for good behaviour at school","cn":"（在校操行的）良好","g":"[countable]","lab":"British English","ex":{"en":"Other schools already have merit systems in place that reward good behaviour and attitudes.","cn":"其他学校已经制定了奖励良好行为和态度的奖励制度。"}},{"en":"to deserve praise, attention, etc.","cn":"值得（表扬、关注等）","ex":{"en":"He claims that their success was not merited.","cn":"他声称他们不应该获得成功。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"良好品质;价值","en":"If something has merit, it has good or worthwhile qualities.","ex":{"en":"The argument seemed to have considerable merit","cn":"这个论点似乎颇有价值。"}},{"pos":"N-PLURAL 复数名词","cn":"优点;长处;优势","en":"The merits of something are its advantages or other good points.","ex":{"en":"They have been persuaded of the merits of peace.","cn":"他们被劝服，认识到了和平的好处。"}},{"pos":"VERB 动词","cn":"值得;应受到","en":"If someone or something merits a particular action or treatment, they deserve it.","ex":{"en":"He said he had done nothing wrong to merit a criminal investigation","cn":"他说自己没有干坏事，不应该受到刑事调查。"}},{"pos":"PHRASE 短语","cn":"根据事物本身的情况(来评价)","en":"If you judge something or someone on merit or on their merits, your judgment is based on what you notice when you consider them, rather than on things that you know about them from other sources.","ex":{"en":"Everybody is selected on merit","cn":"每个人都是凭个人才能入选的。"}}]},"examples":[{"en":"We will consider each case on its (own) merits (= without considering any other issues, feelings, etc.).","cn":"我们将根据每件事情本身的情况来考虑。"},{"en":"They weighed up the relative merits of the four candidates.","cn":"他们对四名候选人各自的优点作了比较。"}]},"metis":{"oxford":{"phon":"meɪˈtiː","pos":"noun","senses":[{"en":"(especially in Canada) a member of a people whose ancestors are both Indigenous and European, especially those whose European ancestors came to Canada from France in the 17th or 18th century","cn":"米提人；梅蒂人（尤指加拿大土著和欧洲人或有土著和欧洲血统的混血儿）"}]},"media":{"uk":"media/uk/metis__gb_1.mp3","us":"media/us/metis__us_1.mp3"}},"meter":{"media":{"uk":"media/uk/meter__gb_1.mp3","us":"media/us/meter__us_1.mp3"},"oxford":{"phon":"ˈmiːtə(r)","pos":"noun","senses":[{"en":"a device that measures and records the amount of electricity, gas, water, etc. that you have used or the time and distance you have travelled, etc.","cn":"（用于测量电、煤气、水等，以及时间和距离的）计量器，计量表","ex":{"en":"A man came to read the gas meter.","cn":"一个男子来查了煤气表。"}},{"en":"a machine next to the road that you put money into when you park your car next to it","cn":"停车计时器"},{"en":"a device for measuring the thing mentioned","cn":"计；仪；表","ex":{"en":"speedometer","cn":"速度计"}},{"en":"a unit for measuring length; a hundred centimetres","cn":"米；公尺","g":"[countable]","lab":"US English","ex":{"en":"a 50-meter swimming pool","cn":"一个50米的游泳池"}},{"en":"used in the name of races","cn":"用于竞赛名称","g":"[countable, uncountable]","lab":"US English","ex":{"en":"Who holds the record in the 100 meters?","cn":"100 米纪录是谁保持的？"}},{"en":"the arrangement of strong and weak stresses in lines of poetry that produces the rhythm; a particular example of this","cn":"（诗的）格律","g":"[uncountable, countable]","lab":"US English"},{"en":"to measure something (for example how much gas, electricity, etc. has been used) using a meter","cn":"用仪表计量","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"计量仪;计量表","en":"A meter is a device that measures and records something such as the amount of gas or electricity that you have used.","ex":{"en":"He was there to read the electricity meter","cn":"他到那里抄电表。"}},{"pos":"VERB 动词","cn":"用表计量(耗用的煤气、电等)","en":"To meter something such as gas or electricity means to use a meter to measure how much of it people use, usually in order to calculate how much they have to pay.","ex":{"en":"Only a third of these households thought it reasonable to meter water","cn":"这些家庭当中只有三分之一认为用水表计量是合理的。"}},{"pos":"N-COUNT 可数名词","cn":"同 parking meter","en":"A meter is the same as a parking meter ."}]},"examples":[{"en":"The cab driver left the meter running while he waited for us.","cn":"在等我们的时候，出租车司机让计程表继续走字。"},{"en":"A man came to read the gas meter.","cn":"有个男子来查过煤气表。"}]},"memorable":{"oxford":{"phon":"ˈmemərəbl","pos":"adjective","senses":[{"en":"worth remembering or easy to remember, especially because of being special or unusual","cn":"值得纪念的；难忘的","ex":{"en":"The holiday provided many memorable moments.","cn":"这个假期留下了许多难忘的时刻。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难忘的;值得纪念的","en":"Something that is memorable is worth remembering or likely to be remembered, because it is special or very enjoyable.","ex":{"en":"...the perfect setting for a nostalgic memorable day","cn":"度过令人难忘的怀旧一日的绝佳环境"}}]},"media":{"uk":"media/uk/memorable__gb_1.mp3","us":"media/us/memorable__us_1.mp3"},"examples":[{"en":"a truly memorable occasion","cn":"非常难忘的时刻"},{"en":"We want to make this a truly memorable day for the children.","cn":"我们想让今天成为孩子们永远难忘的日子。"}]},"meeting":{"media":{"uk":"media/uk/meeting__gb_1.mp3","us":"media/us/meeting__us_1.mp3"},"oxford":{"phon":"ˈmiːtɪŋ","pos":"noun","senses":[{"en":"an occasion when people come together to discuss or decide something","cn":"会议；集会","g":"[countable]","ex":{"en":"A hundred people attended the public meeting.","cn":"一百人参加了这次公开会议。"}},{"en":"the people at a meeting","cn":"（统称）与会者","g":"[singular]","ex":{"en":"The meeting will discuss how to resolve the ongoing crisis in this region.","cn":"会议将讨论如何解决该地区目前的危机。"}},{"en":"a situation in which two or more people meet together, because they have arranged it or by chance","cn":"会面；集会；集合","g":"[countable]","ex":{"en":"At our first meeting I was nervous.","cn":"我们第一次见面时我很紧张。"}},{"en":"a sports event or set of races, especially for horses","cn":"运动会；（尤指）赛马","g":"[countable]","lab":"British English","ex":{"en":"an athletics meeting","cn":"运动会"}},{"en":"an occasion when people, especially Quakers, come together for worship","cn":"（尤指贵格会的）教徒集会","ex":{"en":"Quaker meetings are held here every week.","cn":"贵格会每周都在这里举行会议。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"会议;集会","en":"A meeting is an event in which a group of people come together to discuss things or make decisions.","ex":{"en":"Can we have a meeting to discuss that?","cn":"我们可以开会来讨论那件事吗？"}},{"pos":"N-COUNT 可数名词","cn":"(有意或无意的)碰见，遇上","en":"When you meet someone, either by chance or by arrangement, you can refer to this event as a meeting .","ex":{"en":"In January, 37 years after our first meeting, I was back in the studio with Denis","cn":"那是1月，在我们初次相遇37年之后，我和丹尼斯一同回到了工作室。"}}]},"examples":[{"en":"I'll be in a meeting all morning — can you take my calls?","cn":"我整个上午都要开会，你能不能帮我接一下电话？"},{"en":"He remembered their childhood meetings with nostalgia.","cn":"他怀念地回忆起他们孩提时代的聚会。"}]},"mental":{"media":{"uk":"media/uk/mental__gb_1.mp3","us":"media/us/mental__us_1.mp3"},"oxford":{"phon":"ˈmentl","pos":"adjective","senses":[{"en":"connected with or happening in the mind; involving the process of thinking","cn":"思想的；精神的；思考的；智力的","g":"[usually before noun]","ex":{"en":"the mental process of remembering","cn":"记忆的心理过程"}},{"en":"connected with the state of health of the mind or with the treatment of illnesses of the mind","cn":"精神健康的；精神病治疗的","g":"[usually before noun]","lab":"old-fashioned","ex":{"en":"a mental disorder/illness","cn":"心理障碍／疾病"}},{"en":"crazy","cn":"精神失常；发疯","g":"[not usually before noun]","lab":"British English, slang, sometimes offensive，，，，","ex":{"en":"Watch him. He's mental.","cn":"看着他，他疯了。"}},{"en":"doing the action of; having the result of","cn":"〔表示做某事的动作﹑动作的实施者或结果〕","ex":{"en":"governmental","cn":"政府的"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"智力的;脑力的;思考的","en":"Mental means relating to the process of thinking.","ex":{"en":"...the mental development of children.","cn":"儿童的智力发展"}},{"pos":"ADJ 形容词","cn":"心理上的;精神上的","en":"Mental means relating to the state or the health of a person's mind.","ex":{"en":"The mental state that had created her psychosis was no longer present.","cn":"导致她精神失常的那种心理状态已经消失了。"}},{"pos":"ADJ 形容词","cn":"内心的;在头脑中进行的","en":"A mental act is one that involves only thinking and not physical action.","ex":{"en":"Practise mental arithmetic when you go out shopping","cn":"外出购物的时候练习一下心算。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"疯狂的;发疯的","en":"If you say that someone is mental, you mean that you think they are mad.","ex":{"en":"I just said to him 'you must be mental'.","cn":"我刚才对他说：“你一定是疯了。”"}},{"pos":"PHRASE 短语","cn":"记在脑子里;把…牢记在心","en":"If you make a mental note of something, you make an effort to store it in your memory so that you will not forget it.","ex":{"en":"She made a mental note to have his prescription refilled.","cn":"她记着要拿他的处方再配一回药。"}}]},"examples":[{"en":"My dad will go mental (= be very angry) when he finds out.","cn":"我父亲要是发现了，他会气疯的。"},{"en":"Do you have a mental picture of what it will look like?","cn":"在你想像中它会是什么样子？"}]},"message":{"media":{"uk":"media/uk/message__gb_1.mp3","us":"media/us/message__us_1.mp3"},"oxford":{"phon":"ˈmesɪdʒ","pos":"noun","senses":[{"en":"a written or spoken piece of information, etc. that you send to somebody or leave for somebody when you cannot speak to them yourself","cn":"（书面或口头的）信息，消息，音信","ex":{"en":"There were no messages for me at the hotel.","cn":"旅馆里没有给我的留言。"}},{"en":"a piece of information sent in electronic form, for example by email or mobile phone","cn":"电邮信息；（手机）短信息","ex":{"en":"an email/a text/an SMS message","cn":"电邮信息；手机短信"}},{"en":"an important moral, social or political idea that a book, speech, etc. is trying to communicate","cn":"（书、演讲等的）要旨，要点，教训","g":"[usually singular]","ex":{"en":"a film with a strong religious message","cn":"有强烈的宗教寓意的电影"}},{"en":"a piece of information that is sent from the brain to a part of the body, or from a part of the body to the brain","cn":"（从大脑发给身体某部位或身体某部位向大脑发送的）信息","ex":{"en":"The message arrives in your brain in a fraction of a second.","cn":"信息瞬间便可传递到大脑。"}},{"en":"shopping","cn":"购物；买东西","g":"[plural]","lab":"Scottish English, Irish English，，","ex":{"en":"to do the messages","cn":"买东西"}},{"en":"to send a text message, or a message through an instant messaging service, etc. to somebody","cn":"（给某人）发短信，发即时信息","ex":{"en":"Fiona just messaged me.","cn":"菲奥纳刚给我发来电邮。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音信;消息;留言","en":"A message is a piece of information or a request that you send to someone or leave for them when you cannot speak to them directly.","ex":{"en":"I got a message you were trying to reach me","cn":"我收到一条留言，说你想跟我联系。"}},{"pos":"N-COUNT 可数名词","cn":"(书、戏剧等的)要旨，主题思想，寓意","en":"The message that someone is trying to communicate, for example in a book or play, is the idea or point that they are trying to communicate.","ex":{"en":"The report's message was unequivocal","cn":"报告中传达的信息是明确的。"}},{"pos":"VERB 动词","cn":"(用电脑、手机等)给…发消息，给…留言","en":"If you message someone, you send them a message electronically using a computer or another device such as a mobile phone.","ex":{"en":"People who message a lot feel unpopular if they don't get many back","cn":"如果人们发出大量短信但收到的回复却不多，就会觉得自己不受欢迎。"}}]},"examples":[{"en":"I've been trying to get you all day — don't you ever listen to your messages?","cn":"我整天都在设法跟你联系，难道你就没有听一下电话留言？"},{"en":"When he started looking at his watch, I got the message and left.","cn":"他开始看表了，我明白他的意思，就走了。"}]},"mend":{"oxford":{"phon":"mend","pos":"verb","senses":[{"en":"to repair something that has been damaged or broken so that it can be used again","cn":"修理；修补","g":"[transitive]","lab":"British English","ex":{"en":"Could you mend my bike for me?","cn":"你能帮我修一下自行车吗？"}},{"en":"to repair a hole in a piece of clothing, etc.","cn":"缝补；织补","g":"[transitive]","ex":{"en":"He mended shoes for a living.","cn":"他靠修鞋为生。"}},{"en":"to find a solution to a problem or disagreement","cn":"弥合（分歧）；解决（争端）","g":"[transitive]","ex":{"en":"They tried to mend their differences.","cn":"他们试图消除他们之间的分歧。"}},{"en":"to improve in health after being ill","cn":"痊愈；恢复健康","g":"[intransitive]","lab":"old-fashioned","ex":{"en":"He's mending slowly after the operation.","cn":"手术后，他正在缓慢好转。"}},{"en":"to join up and return to normal","cn":"愈合；恢复","g":"[intransitive]"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"修理;修补","en":"If you mend something that is broken or not working, you repair it, so that it works properly or can be used.","ex":{"en":"They took a long time to mend the roof","cn":"他们花了很长时间修缮屋顶。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)康复;(使)痊愈;(使)愈合","en":"If a person or a part of their body mends or is mended, they get better after they have been ill or have had an injury.","ex":{"en":"You'll mend. The X-rays show that your arm will heal all right","cn":"你会康复的。X光照片显示你的胳膊能够较好地复原。"}},{"pos":"VERB 动词","cn":"弥合(分歧);解决(争端)","en":"If you try to mend divisions between people, you try to end the disagreements or quarrels between them.","ex":{"en":"He sent Evans as his personal envoy to discuss ways to mend relations between the two countries","cn":"他派埃文斯以私人特使的身份前往商讨修复两国关系的途径。"}},{"pos":"PHRASE 短语","cn":"(关系)正在改善;(形势)正在好转","en":"If a relationship or situation is on the mend after a difficult or unsuccessful period, it is improving.","ex":{"en":"More evidence that the economy was on the mend was needed.","cn":"需要更多证据来证明经济正在好转。"}},{"pos":"PHRASE 短语","cn":"(病人)正在恢复之中，正在逐渐好起来","en":"If you are on the mend after an illness or injury, you are recovering from it.","ex":{"en":"The baby had been poorly but seemed on the mend.","cn":"宝宝生病了，但似乎正在好起来。"}},{"pos":"PHRASE 短语","cn":"改过自新;改邪归正","en":"If someone who has been behaving badly mends their ways, they begin to behave well.","ex":{"en":"He has promised drastic disciplinary action if they do not mend their ways.","cn":"如果他们不改邪归正的话，他保证一定严惩不贷。"}},{"pos":"","cn":"","en":"to mend fences→see: ;"}]},"media":{"uk":"media/uk/mend__gb_1.mp3","us":"media/us/mend__us_1.mp3","img":["media/ldoce/img/repair.jpg"]},"examples":[{"en":"They tried to mend their differences.","cn":"他们试图消除他们之间的分歧。"},{"en":"Could you mend my bike for me?","cn":"你能帮我修一下自行车吗？"}]},"methodology":{"media":{"uk":"media/uk/methodology__gb_1.mp3","us":"media/us/methodology__us_1.mp3"},"oxford":{"phon":"ˌmeθəˈdɒlədʒi","pos":"noun","senses":[{"en":"a set of methods and principles used to perform a particular activity","cn":"（从事某一活动的）方法，原则","ex":{"en":"recent changes in the methodology of language teaching","cn":"语言教学法最近的变化"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（进行教学、研究等的）方法论,方法学，一套方法","en":"A methodology is a system of methods and principles for doing something, for example for teaching or for carrying out research.","ex":{"en":"Teaching methodologies vary according to the topic","cn":"题目不同，教学法也不一样。"}}]},"examples":[{"en":"recent changes in the methodology of language teaching","cn":"语言教学法最近的变化"},{"en":"methodological problems","cn":"方法问题"}]},"meaningfully":{"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"有用意地;有目的地;意味深长地","en":"You use meaningfully to indicate that someone has deliberately chosen their words in order to express something in a way which is not obvious but which is understood by the person they are talking to.","ex":{"en":"'I have a knack for making friends, you know,' she added meaningfully","cn":"“你知道，我交朋友有一套的，”她故意补充说。"}}]},"media":{"uk":"media/uk/meaningfully__gb_1.mp3","us":"media/us/meaningfully__us_1.mp3"},"examples":[{"en":"Without more data we cannot make a meaningful comparison of the two systems.","cn":""},{"en":"Teaching history to five-year-olds in a meaningful way can be very difficult.","cn":""}],"oxford":{"phon":"ˈmiːnɪŋfəli","pos":"adverb","senses":[{"en":"in a serious and important way","cn":"严肃的；重要的；重大的","ex":{"en":"to participate meaningfully in a debate","cn":"有意义地参与辩论"}},{"en":"in a way that is intended to communicate or express something to somebody, without any words being spoken","cn":"意味深长的；意在言外的","ex":{"en":"to glare/glance/stare meaningfully at somebody","cn":"有意义地瞪视/瞥视/凝视某人"}}]}},"medical":{"media":{"uk":"media/uk/medical__gb_1.mp3","us":"media/us/medical__us_1.mp3"},"oxford":{"phon":"ˈmedɪkl","pos":"adjective","senses":[{"en":"connected with illness and injury and their treatment","cn":"医学的；医疗的","ex":{"en":"medical care/treatment","cn":"医疗；治疗"}},{"en":"connected with ways of treating illness that do not involve cutting the body","cn":"内科的","ex":{"en":"There are also medical and surgical treatment options for the condition.","cn":"对于这种情况，还有药物和手术治疗选择。"}},{"en":"a careful and complete examination of your body that a doctor does, for example before you start a particular job","cn":"体检；健康检查","ex":{"en":"He was accepted onto the course after passing the medical.","cn":"体检合格后，他获准上这门课。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"医学的;医疗的;医术的","en":"Medical means relating to illness and injuries and to their treatment or prevention.","ex":{"en":"Several police officers received medical treatment for cuts and bruises.","cn":"几名警官因割伤和擦伤而接受了医治。"}},{"pos":"N-COUNT 可数名词","cn":"体格检查;体检","en":"A medical is a thorough examination of your body by a doctor, for example before you start a new job."}]},"examples":[{"en":"a medical certificate (= a statement by a doctor that gives details of your state of health)","cn":"健康证明"},{"en":"medical advances/care/research","cn":"医学上的进展；医疗；医学研究"}]},"metals":{"oxford":{"phon":"ˈmetl","pos":"noun","senses":[{"en":"a type of solid mineral substance that is usually hard and shiny and that heat and electricity can travel through, for example tin, iron and gold","cn":"金属"}]},"media":{"uk":"media/uk/metal__gb_1.mp3","us":"media/us/metal__us_1.mp3"}},"meanwhile":{"media":{"uk":"media/uk/meanwhile__gb_1.mp3","us":"media/us/meanwhile__us_1.mp3"},"oxford":{"phon":"ˈmiːnwaɪl","pos":"adverb","senses":[{"en":"while something else is happening","cn":"同时；与此同时","lab":"informal","ex":{"en":"Leave the cake to cool completely. Meanwhile, make the topping.","cn":"让蛋糕完全冷却。同时，制作配料。"}},{"en":"in the period of time between two times or two events","cn":"在此期间；与此同时","lab":"informal","ex":{"en":"The doctor will see you again next week. Meanwhile, you must rest as much as possible.","cn":"医生下周还会给你看病。在此期间，你一定要尽可能多休息。"}},{"en":"used to compare two aspects of a situation","cn":"（比较两方面）对比之下","ex":{"en":"Stress can be extremely damaging to your health. Exercise, meanwhile, can reduce its effects.","cn":"压力可能严重损害你的健康，锻炼则可以减轻这些损害。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"同时;与此同时","en":"Meanwhile means while a particular thing is happening.","ex":{"en":"Brush the aubergines with oil, add salt and pepper, and bake till soft. Meanwhile, heat the remaining oil in a heavy pan","cn":"把油涂在茄子上，加盐和胡椒烤至松软。与此同时，在厚锅中加热剩余的油。"}},{"pos":"ADV 副词","cn":"在此期间;其间","en":"Meanwhile means in the period of time between two events.","ex":{"en":"You needn't worry; I'll be ready to greet them. Meanwhile I'm off to discuss the Fowler's party with Felix.","cn":"你不必担心，我会招呼他们的。其间，我还要去跟费利克斯商量一下福勒举办聚会的事。"}},{"pos":"ADV 副词","cn":"(引出某一情形的另一方面，尤指与前面提到的完全相反时)与之相比，然而","en":"You use meanwhile to introduce a different aspect of a particular situation, especially one that is completely opposite to the one previously mentioned.","ex":{"en":"He had always found his wife's mother a bit annoying. The mother-daughter relationship, meanwhile, was close.","cn":"他总是觉得丈母娘有点烦人，然而她们母女之间的关系却非常亲密。"}}]},"examples":[{"en":"Bob spent fifteen months alone on his yacht. Ann, meanwhile, took care of the children on her own.","cn":"鲍勃独自在他的游艇上待了十五个月。在这段时间，安一个人照顾孩子。"},{"en":"The doctor will see you again next week. Meanwhile, you must rest as much as possible.","cn":"医生下周还会给你看病。在此期间，你一定要尽可能多休息。"}]},"meteorological":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"气象学的","en":"Meteorological means relating to meteorology.","ex":{"en":"...adverse meteorological conditions.","cn":"不利的气象条件"}}]},"media":{"uk":"media/uk/meteorological__gb_1.mp3","us":"media/us/meteorological__us_1.mp3"},"oxford":{"phon":"ˌmiːtiərəˈlɒdʒɪkl","pos":"adjective","senses":[{"en":"connected with the earth's atmosphere and its changes, especially in the way they affect the weather","cn":"气象的","ex":{"en":"meteorological conditions/data","cn":"气象条件/数据"}}]}},"mentality":{"oxford":{"phon":"menˈtæləti","pos":"noun","senses":[{"en":"the particular attitude or way of thinking of a person or group","cn":"心态；思想状况；思想方法","ex":{"en":"I can’t understand the mentality of people who are unkind to their pets.","cn":"我不能理解那些对自己宠物不好的人的心理。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"心态;思维方式","en":"Your mentality is your attitudes and your way of thinking.","ex":{"en":"...a criminal mentality","cn":"犯罪心态"}}]},"media":{"uk":"media/uk/mentality__gb_1.mp3","us":"media/us/mentality__us_1.mp3"},"examples":[{"en":"I cannot understand the mentality of football hooligans.","cn":"我无法理解足球流氓的心态。"},{"en":"a criminal/ghetto mentality","cn":"犯罪心态；种族聚居区的思想意识"}]},"metaphorically":{"oxford":{"phon":"ˌmetəˈfɒrɪkli","pos":"adverb","senses":[{"en":"in a way that uses or contains metaphors","cn":"隐喻的；含比喻的；比喻性的","ex":{"en":"I'll leave you in Robin's capable hands—metaphorically speaking, of course!","cn":"我要把你放到罗宾能干的手中。当然，这只是打个比方。"}}]},"media":{"uk":"media/uk/metaphorically__gb_1.mp3","us":"media/us/metaphorically__us_1.mp3"},"examples":[{"en":"I'll leave you in Robin's capable hands — metaphorically speaking, of course!","cn":"我要把你放到罗宾能干的手中。当然，这只是打个比方。"},{"en":"The word has a metaphorical as well as a literal meaning.","cn":""}]},"mediterranean":{"media":{"uk":"media/uk/mediterranean__gb_1.mp3","us":"media/us/mediterranean__us_1.mp3"},"oxford":{"phon":"ˌmedɪtəˈreɪniən","pos":"adjective","senses":[{"en":"relating to the Mediterranean Sea or the countries that surround it; typical of this area","cn":"地中海的；地中海型的","ex":{"en":"a Mediterranean country","cn":"地中海国家"}},{"en":"the Mediterranean Sea or the countries that surround it","cn":"地中海；地中海国家","ex":{"en":"The hotel boasts spectacular views of the Mediterranean.","cn":"这家酒店可以观赏到地中海的壮丽景色。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"地中海","en":"The Mediterranean is the sea between southern Europe and North Africa."},{"pos":"N-PROPER 专有名词","cn":"地中海地区(指欧洲南部地中海附近地区)","en":"The Mediterranean refers to the southern part of Europe, which is next to the Mediterranean Sea.","ex":{"en":"...one of the most dynamic and prosperous cities in the Mediterranean.","cn":"地中海地区最有活力、最为繁荣的城市之一"}},{"pos":"ADJ 形容词","cn":"地中海的;地中海地区的;地中海居民的","en":"Something that is Mediterranean is characteristic of or belongs to the people or region around the Mediterranean Sea.","ex":{"en":"...the classic Mediterranean diet.","cn":"地道的地中海饮食"}}]},"examples":[{"en":"a Mediterranean country","cn":"地中海国家"},{"en":"a Mediterranean climate","cn":"地中海气候"}]},"media":{"media":{"uk":"media/uk/media__gb_1.mp3","us":"media/us/media__us_1.mp3"},"oxford":{"phon":"ˈmiːdiə","pos":"noun","senses":[{"en":"the main ways that large numbers of people receive information and entertainment, that is television, radio, newspapers and the internet","cn":"大众传播媒介，大众传播工具（指电视、广播、报纸、互联网）","g":"[countable + singular or plural verb]","ex":{"en":"the national/international media","cn":"国内／国际媒体"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"媒体，传播工具，传播媒介(如电视、广播、报纸和杂志等)","en":"You can refer to television, radio, newspapers, and magazines as the media .","ex":{"en":"It is hard work and not a glamorous job as portrayed by the media.","cn":"这是份苦差，并非像媒体描绘的那般令人向往。"}},{"pos":"","cn":"(medium 的复数之一)","en":"Media is a plural of medium ."}]},"examples":[{"en":"Any event attended by the actor received widespread media coverage.","cn":"这位演员参加任何一项活动，媒体都作了广泛报道。"},{"en":"The trial was fully reported in the media.","cn":"媒体对这次审判进行了全面报道。"}]},"metaphorical":{"media":{"uk":"media/uk/metaphorical__gb_1.mp3","us":"media/us/metaphorical__us_1.mp3"},"oxford":{"phon":"ˌmetəˈfɒrɪkl","pos":"adjective","senses":[{"en":"connected with or containing metaphors","cn":"隐喻的；含比喻的；比喻性的","ex":{"en":"metaphorical language","cn":"比喻的语言"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"隐喻的;比喻意义的;象征的","en":"You use the word metaphorical to indicate that you are not using words with their ordinary meaning, but are describing something by means of an image or symbol.","ex":{"en":"It turns out Levy is talking in metaphorical terms","cn":"利维原来说的是一种比喻。"}}]},"examples":[{"en":"I'll leave you in Robin's capable hands — metaphorically speaking, of course!","cn":"我要把你放到罗宾能干的手中。当然，这只是打个比方。"},{"en":"metaphorical language","cn":"比喻的语言"}]},"melting":{"media":{"uk":"media/uk/melting__gb_1.mp3","us":"media/us/melting__us_1.mp3"},"oxford":{"phon":"ˈmeltɪŋ","pos":"adjective","senses":[{"en":"persuading you to feel love or sympathy","cn":"动人的；柔情似水的；令人爱怜的；令人同情的","ex":{"en":"his melting eyes","cn":"他那双能打动人的眼睛"}}]},"examples":[{"en":"his melting eyes","cn":"他那双能打动人的眼睛"}]},"meat":{"media":{"uk":"media/uk/meat__gb_1.mp3","us":"media/us/meat__us_1.mp3","img":["media/ldoce/img/meat.jpg"]},"oxford":{"phon":"miːt","pos":"noun","senses":[{"en":"the soft part of an animal or a bird that can be eaten as food; a particular type of this","cn":"肉；（某种）食用肉","g":"[uncountable, countable]","lab":"figurative, humorous，，","ex":{"en":"a piece/slice of meat","cn":"一块／一片肉"}},{"en":"the important or interesting part of something","cn":"重要的部分；有趣的部分","g":"[uncountable]","ex":{"en":"This chapter contains the real meat of the writer's argument.","cn":"这一章包含了作者的主要论点。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(供食用的)肉","en":"Meat is flesh taken from a dead animal that people cook and eat.","ex":{"en":"Meat and fish are relatively expensive.","cn":"肉和鱼相对来说比较贵。"}},{"pos":"PHRASE 短语","cn":"喜欢做的事;感兴趣的事","en":"If you say something is meat and drink to someone, you mean that they enjoy it very much.","ex":{"en":"What normal people considered pressure was meat and drink to him.","cn":"一般人认为有压力的事情在他看来却是快乐无比的事。"}},{"pos":"PHRASE 短语","cn":"最基本的部分;根本部分;关键","en":"If you refer to the meat and potatoes of something, you mean its most basic, simple, and essential parts.","ex":{"en":"What they want is the meat and potatoes of how we're going to improve this country and get our country moving again.","cn":"他们想知道的是我们如何改善国家、让其恢复活力的基本方法。"}}]},"examples":[{"en":"This chapter contains the real meat of the writer's argument.","cn":"这一章包含了作者的主要论点。"},{"en":"There's not much meat on this chop.","cn":"这块猪排没什么肉。"}]},"metal":{"media":{"uk":"media/uk/metal__gb_1.mp3","us":"media/us/metal__us_1.mp3"},"oxford":{"phon":"ˈmetl","pos":"noun","senses":[{"en":"a type of solid mineral substance that is usually hard and shiny and that heat and electricity can travel through, for example tin, iron and gold","cn":"金属","ex":{"en":"a piece/sheet of metal","cn":"一块／一片金属"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"金属","en":"Metal is a hard substance such as iron, steel, gold, or lead.","ex":{"en":"...pieces of furniture in wood, metal and glass","cn":"用木料、金属和玻璃制成的一件件家具"}}]},"examples":[{"en":"The frame is made of metal.","cn":"框子是用金属做的。"},{"en":"a metal pipe/bar/box","cn":"金属管/棍/盒子"}]},"med":{"oxford":{"phon":"med","pos":"adjective","senses":[{"en":"medical","cn":"医学的；医疗的","ex":{"en":"a med student","cn":"医学生"}}]},"media":{"uk":"media/uk/med__gb_1.mp3","us":"media/us/med__us_1.mp3"},"examples":[{"en":"She's in med school.","cn":"她在念医学。"},{"en":"a med student","cn":"医学系的学生"}]},"mercilessly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"cruel and showing no kindness or forgiveness","cn":""},{"en":"heat, cold etc that is very great or strong and unpleasant, and does not stop","cn":""}]},"examples":[{"en":"It brings some relief from the merciless summer heat.","cn":"","src":"ld"}],"media":{"uk":"media/uk/mercilessly__gb_1.mp3","us":"media/us/mercilessly__us_1.mp3"},"oxford":{"phon":"ˈmɜːsɪləsli","pos":"adverb","senses":[{"en":"in a way that shows no sympathy and is not kind","cn":"毫不留情地","ex":{"en":"His friends teased him mercilessly when they found the poem.","cn":"当他的朋友们发现这首诗时，他们无情地嘲笑他。"}}]}},"mess":{"media":{"uk":"media/uk/mess__gb_1.mp3","us":"media/us/mess__us_1.mp3"},"oxford":{"phon":"mes","pos":"noun","senses":[{"en":"a dirty or untidy state","cn":"肮脏；杂乱；不整洁","g":"[countable, usually singular]","sc":"untidy state","ex":{"en":"The room was in a mess.","cn":"房间杂乱不堪。"}},{"en":"a situation that is full of problems, usually because of a lack of organization or because of mistakes that somebody has made","cn":"（组织欠佳或人为导致的）麻烦，困境，混乱","g":"[countable, usually singular]","lab":"ironic","sc":"difficult situation","ex":{"en":"The economy is in a mess.","cn":"经济陷入了困境。"}},{"en":"a person who is dirty or whose clothes and hair are not tidy","cn":"不整洁（或邋遢、不修边幅）的人","g":"[singular]","sc":"person","ex":{"en":"You're a mess!","cn":"你真邋遢！"}},{"en":"a person who has serious problems and is in a bad mental condition","cn":"有严重问题且精神失常的人","g":"[singular]","lab":"informal","sc":"person","ex":{"en":"When my wife left me I was a total mess.","cn":"妻子离开我的时候，我简直一团糟。"}},{"en":"the excrement (= solid waste matter) of an animal, usually a dog or cat","cn":"（狗、猫等的）粪便","g":"[uncountable, countable]","lab":"informal","sc":"animal waste"},{"en":"a lot of something","cn":"大量；许多","g":"[singular]","lab":"North American English, informal，，","sc":"a lot","ex":{"en":"There's a mess of fish down there, so get your lines in the water.","cn":"那底下有很多鱼，快下钩吧。"}},{"en":"a building or room in which members of the armed forces have their meals","cn":"（军队的）食堂，餐厅","g":"[countable]","lab":"especially in North American English","sc":"armed forces","ex":{"en":"the officers’ mess","cn":"军官食堂"}},{"en":"to make something dirty or untidy","cn":"使不整洁；弄脏；弄乱","g":"[transitive]","lab":"especially North American English, informal，，","sc":"make untidy","ex":{"en":"Careful—you're messing my hair.","cn":"小心，你弄乱我的头发了。"},"pos":"verb"},{"en":"to empty its bowels somewhere that it should not","cn":"随地便溺","g":"[intransitive]","sc":"of an animal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"脏乱;凌乱;不整洁","en":"If you say that something is a mess or in a mess, you think that it is in an untidy state.","ex":{"en":"The house is a mess","cn":"屋里一片狼藉。"}},{"pos":"N-VAR 可变名词","cn":"困境;麻烦;混乱","en":"If you say that a situation is a mess, you mean that it is full of trouble or problems. You can also say that something is in a mess .","ex":{"en":"I've made such a mess of my life.","cn":"我把自己的生活弄得一团糟。"}},{"pos":"N-VAR 可变名词","cn":"(意外滴落的)液体(或黏稠物)","en":"A mess is something liquid or sticky that has been accidentally dropped on something.","ex":{"en":"Finally, making a dreadful mess, they devour the fruit","cn":"最后，他们狼吞虎咽地吃起了水果，果汁滴得到处都是。"}},{"pos":"N-COUNT 可数名词","cn":"(军队的)餐厅，食堂","en":"The mess at a military base or military barracks is the building in which members of the armed forces can eat or relax.","ex":{"en":"...a party at the officers' mess","cn":"在军官餐厅举行的聚会"}},{"pos":"","cn":"","en":"相关词组：mess around mess up mess with"}]},"examples":[{"en":"‘ What a mess! ’ she said, surveying the scene after the party.","cn":"看着聚会后的场面，她说：“真是一片狼藉！”"},{"en":"The biggest question is how they got into this mess in the first place.","cn":"关键问题是他们是怎么惹出这样的麻烦的。"}]},"metadata":{"oxford":{"phon":"ˈmetədeɪtə","pos":"noun","senses":[{"en":"information that describes other information in order to help you understand or use it","cn":"元数据","ex":{"en":"In the metadata she found the author and location of the file.","cn":"她从元数据中找到了文件的作者和位置。"}}]},"media":{"uk":"media/uk/metadata__gb_1.mp3","us":"media/us/metadata__us_2.mp3"},"examples":[{"en":"In the metadata she found the author and location of the file.","cn":"她从元数据中找到了文件的作者和位置。"}]},"meditation":{"media":{"uk":"media/uk/meditation__gb_1.mp3","us":"media/us/meditation__us_1.mp3"},"oxford":{"phon":"ˌmedɪˈteɪʃn","pos":"noun","senses":[{"en":"the practice of focusing your mind in silence, especially for religious reasons or in order to make your mind calm","cn":"冥想；入静","g":"[uncountable]","ex":{"en":"She found peace through yoga and meditation.","cn":"她通过瑜伽和冥想找到了宁静。"}},{"en":"the activity of thinking deeply about something, especially so that you do not notice the people or things around you","cn":"沉思；深思","g":"[uncountable]","ex":{"en":"He was deep in meditation and didn't see me come in.","cn":"他正在沉思，没有看见我进来。"}},{"en":"serious thoughts on a particular subject that somebody writes down or speaks","cn":"沉思录","g":"[countable, usually plural]","lab":"formal","ex":{"en":"his meditations on life and art","cn":"他对生活和艺术的沉思录"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（宗教中）默想，打坐，冥想","en":"Meditation is the act of remaining in a silent and calm state for a period of time, as part of a religious training, or so that you are more able to deal with the problems of everyday life.","ex":{"en":"Many busy executives have begun to practice yoga and meditation.","cn":"许多忙碌的主管开始练习瑜伽和冥想。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"深思熟虑;苦思冥想","en":"Meditation is the act of thinking about something very carefully and deeply for a long time.","ex":{"en":"...the man, lost in meditation, walking with slow steps along the shore","cn":"这名陷入沉思中的男子，沿着岸边慢慢地走着"}},{"pos":"N-COUNT 可数名词","cn":"（关于某主题的）感想,沉思录","en":"A meditation on a particular subject is something such as a piece of writing or a speech which expresses deep thoughts about that subject.","ex":{"en":"In fact, the entire novel is a long meditation on childbearing and mortality","cn":"实际上，整部小说就是一部关于生儿育女与道德伦理的长篇沉思录。"}}]},"examples":[{"en":"She found peace through yoga and meditation.","cn":"她通过瑜伽和冥想找到了宁静。"},{"en":"He was deep in meditation and didn't see me come in.","cn":"他正在沉思，没有看见我进来。"}]},"measurement":{"media":{"uk":"media/uk/measurement__gb_1.mp3","us":"media/us/measurement__us_1.mp3"},"oxford":{"phon":"ˈmeʒəmənt","pos":"noun","senses":[{"en":"the act or the process of finding the size, quantity or degree of something","cn":"测量；度量","g":"[uncountable, countable]","ex":{"en":"the metric system of measurement","cn":"公制度量衡"}},{"en":"the size, length or amount of something","cn":"（某物的）尺寸，长度，数量","g":"[countable, usually plural]","ex":{"en":"to take somebody’s chest/waist measurement","cn":"量某人的胸围／腰围"}},{"en":"a unit or system of measuring","cn":"测量单位","g":"[countable]","ex":{"en":"A hand is a measurement used for measuring horses.","cn":"掌宽是测量马匹的单位。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常以数字形式呈现的）测量结果","en":"A measurement is a result, usually expressed in numbers, that you obtain by measuring something.","ex":{"en":"We took lots of measurements","cn":"我们得到了许多测量结果。"}},{"pos":"N-VAR 可变名词","cn":"测量;计量","en":"Measurement of something is the process of measuring it in order to obtain a result expressed in numbers.","ex":{"en":"Measurement of blood pressure can be undertaken by practice nurses.","cn":"测量血压可以由实习护士完成。"}},{"pos":"N-VAR 可变名词","cn":"（质量、价值或影响的）衡量，评估，估量","en":"The measurement of the quality, value, or effect of something is the activity of deciding how great it is.","ex":{"en":"...the measurement of output in the non-market sector.","cn":"评估非市场部门的效益"}},{"pos":"N-PLURAL 复数名词","cn":"三围；(身材)尺寸","en":"Your measurements are the size of your waist, chest, hips, and other parts of your body, which you need to know when you are buying clothes."}]},"examples":[{"en":"The exact measurements of the room are 3 metres 20 by 2 metres 84.","cn":"这间屋子的准确尺寸是长 3.20 米，宽 2.84 米。"},{"en":"Accurate measurement is very important in science.","cn":"在科学领域，精确的测量非常重要。"}]},"melt":{"media":{"uk":"media/uk/melt__gb_1.mp3","us":"media/us/melt__us_1.mp3"},"oxford":{"phon":"melt","pos":"verb","senses":[{"en":"to become or make something become liquid as a result of heating","cn":"（使）熔化，融化","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"The snow showed no sign of melting.","cn":"雪没有一点融化的迹象。"}},{"en":"to become or to make a feeling, an emotion, etc. become gentler and less strong","cn":"（使）软化，变得温柔","g":"[intransitive, transitive]","ex":{"en":"The tension in the room began to melt.","cn":"屋里的紧张气氛开始缓和。"}},{"en":"to become extremely hot","cn":"热坏了","ex":{"en":"Today the temperature got up to 36 degrees and it felt like I was melting.","cn":"今天气温上升到 36 度，我感觉要被烤化了。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)熔化;(使)融化","en":"When a solid substance melts or when you melt it, it changes to a liquid, usually because it has been heated.","ex":{"en":"The snow had melted, but the lake was still frozen solid","cn":"雪已经融化了，但是湖面上仍然冻得结结实实的。"}},{"pos":"VERB 动词","cn":"(情绪等)消失,消散,平息","en":"If something such as your feelings melt, they suddenly disappear and you no longer feel them.","ex":{"en":"His anxiety about the outcome melted, to return later but not yet","cn":"他对未知结果的焦虑消散了，这种焦虑过后还会袭上心头，但至少现在还没有。"}},{"pos":"VERB 动词","cn":"逐渐融入(黑暗、人群等);与…融为一体","en":"If a person or thing melts into something such as darkness or a crowd of people, they become difficult to see, for example because they are moving away from you or are the same colour as the background.","ex":{"en":"The youths dispersed and melted into the darkness","cn":"年轻人散开了，消失在夜幕之中。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(心)软化","en":"If someone or something melts your heart, or if your heart melts, you start to feel love or sympathy towards them.","ex":{"en":"When his lips break into a smile, it is enough to melt any woman's heart","cn":"他粲然一笑就足以让任何女人心软。"}},{"pos":"N-COUNT 可数名词","cn":"（带鱼或肉的）奶酪三明治","en":"A melt is a piece of bread which has meat or fish on it, and melted cheese on top.","ex":{"en":"...a tuna melt.","cn":"金枪鱼奶酪三明治"}},{"pos":"","cn":"","en":"相关词组：melt away melt down"}]},"examples":[{"en":"Her trusting smile melted his heart.","cn":"她那信任的微笑使他的心变软了。"},{"en":"At the first sign of trouble, the crowd melted away.","cn":"人群一看有麻烦，便作鸟兽散。"}]},"mean":{"media":{"uk":"media/uk/mean__gb_1.mp3","us":"media/us/mean__us_1.mp3"},"oxford":{"phon":"miːn","pos":"verb","senses":[{"en":"to have something as a meaning in the same or another language","cn":"表示…的意思；有…含义","sc":"have as meaning","ex":{"en":"What does this sentence mean?","cn":"这个句子是什么意思？"}},{"en":"to have something as a meaning; to represent something","cn":"意思是；表示","sc":"have as meaning","ex":{"en":"What do we mean by democracy?","cn":"我们所说的民主是什么意思？"}},{"en":"to intend to say something on a particular occasion","cn":"（某人说某话）意思是，本意是","lab":"informal","sc":"intend as meaning","ex":{"en":"What did he mean by that remark?","cn":"他说那话是什么意思？"}},{"en":"to have something as a purpose or intention","cn":"打算；意欲；有…的目的","lab":"formal","sc":"have as purpose","ex":{"en":"What did she mean by leaving so early (= why did she do it)?","cn":"她为什么这么早就走了？"}},{"en":"to have something as a result or a likely result","cn":"产生…结果；意味着","sc":"have as result","ex":{"en":"Spending too much now will mean a shortage of cash next year.","cn":"现在花销太多就意味着明年现金短缺。"}},{"en":"to be of value or importance to somebody","cn":"对某人重要（或有价值）","g":"[no passive]","sc":"be important","ex":{"en":"Your friendship means a great deal to me.","cn":"你的友谊对我来说是很珍贵的。"}},{"en":"to intend somebody to be or do something","cn":"想要某人成为；想要某人去做","g":"[often passive]","sc":"intend somebody to be/do something","ex":{"en":"I was never meant for the army (= did not have the qualities needed to become a soldier).","cn":"我根本就不是块当兵的料。"}},{"en":"not willing to give or share things, especially money","cn":"吝啬的；小气的","lab":"British English","sc":"not generous","ex":{"en":"She's always been mean with money.","cn":"她在花钱方面总是非常吝啬。"},"pos":"adjective"},{"en":"unkind, for example by not letting somebody have or do something","cn":"不善良；刻薄","sc":"unkind","ex":{"en":"Don't be so mean to your little brother!","cn":"别对你弟弟那么刻薄！"},"pos":"adjective"},{"en":"likely to become angry or violent","cn":"要发怒的；要发狂的","lab":"especially North American English","sc":"angry/violent","ex":{"en":"That's a mean-looking dog.","cn":"那狗看上去很凶。"},"pos":"adjective"},{"en":"very good and showing skill","cn":"熟练的；出色的","lab":"informal","sc":"showing skill","ex":{"en":"He's a mean tennis player.","cn":"他是一名出色的网球选手。"},"pos":"adjective"},{"en":"average; between the highest and the lowest, etc.","cn":"平均的；介于中间的","g":"[only before noun]","lab":"specialist","sc":"average","ex":{"en":"the mean temperature","cn":"平均气温"},"pos":"adjective"},{"en":"not very great","cn":"平庸的；一般的","lab":"formal","sc":"intelligence","ex":{"en":"This should be clear even to the meanest intelligence.","cn":"就是对智力最平庸的人来说，这也应当是非常明了的。"},"pos":"adjective"},{"en":"poor and dirty in appearance","cn":"又穷又脏的","lab":"literary","sc":"poor","ex":{"en":"mean houses/streets","cn":"脏乱的房屋／街道"},"pos":"adjective"},{"en":"born into or coming from a low social class","cn":"出身卑贱的；社会地位低下的","lab":"old-fashioned","sc":"poor","ex":{"en":"These rights apply even to the meanest labourer.","cn":"这些权利甚至适用于最卑微的劳动者。"},"pos":"adjective"},{"en":"a quality, condition, or way of doing something that is in the middle of two extremes and better than either of them","cn":"中间；中庸；折中","sc":"middle way","ex":{"en":"He needed to find a mean between frankness and rudeness.","cn":"他需要在坦诚与唐突之间找到折中的方法。"},"pos":"noun"},{"en":"the value found by adding together all the numbers in a group, and dividing the total by the number of numbers","cn":"平均数；平均值；算术平均数","lab":"mathematics","sc":"average","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"意思是;表示…的意思;作…解释","en":"If you want to know what a word, code, signal, or gesture means, you want to know what it refers to or what its message is.","ex":{"en":"In modern Welsh, 'glas' means 'blue'","cn":"在现代威尔士语中，glas 意为“蓝色”。"}},{"pos":"VERB 动词","cn":"意指;表示;意思是说","en":"If you ask someone what they mean, you are asking them to explain exactly what or who they are referring to or what they are intending to say.","ex":{"en":"Do you mean me?","cn":"你指的是我吗？"}},{"pos":"VERB 动词","cn":"(某事)对(某人)很重要，要紧,意义重大","en":"If something means something to you, it is important to you in some way.","ex":{"en":"The idea that she witnessed this shameful incident meant nothing to him","cn":"虽然她目睹了这可耻的一幕，但是这对他来说无关紧要。"}},{"pos":"VERB 动词","cn":"表明…存在;表示…属实","en":"If one thing means another, it shows that the second thing exists or is true.","ex":{"en":"An enlarged prostate does not necessarily mean cancer","cn":"前列腺肿大不一定就是癌症。"}},{"pos":"VERB 动词","cn":"导致;产生…的结果","en":"If one thing means another, the first thing leads to the second thing happening.","ex":{"en":"It would almost certainly mean the end of NATO","cn":"这几乎肯定会导致北大西洋公约组织的终结。"}},{"pos":"VERB 动词","cn":"涉及；包含","en":"If doing one thing means doing another, it involves doing the second thing.","ex":{"en":"Children universally prefer to live in peace and security, even if that means living with only one parent","cn":"孩子们普遍愿意过平静安宁的生活，即便这意味着只能与单亲生活在一起。"}},{"pos":"VERB 动词","cn":"对…当真;对…严肃认真","en":"If you say that you mean what you are saying, you are telling someone that you are serious about it and are not joking, exaggerating, or just being polite.","ex":{"en":"He says you're fired if you're not back at work on Friday. And I think he meant it","cn":"他说，如果你星期五还不回去上班的话就解雇你。我想他是当真的。"}},{"pos":"VERB 动词","cn":"有意;故意","en":"If you say that someone meant to do something, you are saying that they did it deliberately.","ex":{"en":"I didn't mean to hurt you","cn":"我无意伤害你。"}},{"pos":"VERB 动词","cn":"本意并非;并未打算","en":"If you say that someone did not mean any harm, offence, or disrespect, you are saying that they did not intend to upset or offend people or to cause problems, even though they may in fact have done so.","ex":{"en":"I'm sure he didn't mean any harm","cn":"我相信他并无恶意。"}},{"pos":"VERB 动词","cn":"计划;打算;准备","en":"If you mean to do something, you intend or plan to do it.","ex":{"en":"Summer is the perfect time to catch up on the new books you meant to read","cn":"夏天是把想读却没读的新书恶补一下的最佳时机。"}},{"pos":"VERB 动词","cn":"注定（或肯定）要…","en":"If you say that something was meant to happen, you believe that it was made to happen by God or fate, and did not just happen by chance.","ex":{"en":"John was constantly reassuring me that we were meant to be together.","cn":"约翰不断安慰我说，我们注定要在一起。"}},{"pos":"PHRASE 短语","cn":"我的意思是，也就是说（用于使表述更加清楚）","en":"You say 'I mean' when making clearer something that you have just said.","ex":{"en":"It was his idea. Gordon's, I mean","cn":"这是他的主意，我是指戈登。"}},{"pos":"PHRASE 短语","cn":"(用于引出主张，尤指证明自己刚才所说的话)","en":"You can use 'I mean' to introduce a statement, especially one that justifies something that you have just said.","ex":{"en":"I'm sure he wouldn't mind. I mean, I was the one who asked him","cn":"我肯定他不会在意的，因为是我问他的。"}},{"pos":"PHRASE 短语","cn":"我的意思是(用于纠正之前所说的话)","en":"You say I mean when correcting something that you have just said.","ex":{"en":"It was law or classics—I mean English or classics.","cn":"是法律或者古典文学——我的意思是英语或古典文学。"}},{"pos":"PHRASE 短语","cn":"理解…的滋味;了解…的影响","en":"If you know what it means to do something, you know everything that is involved in a particular activity or experience, especially the effect that it has on you.","ex":{"en":"I know what it means to lose a child under such tragic circumstances.","cn":"我明白在这种悲惨的情况下失去孩子的滋味。"}},{"pos":"PHRASE 短语","cn":"听说过;了解","en":"If a name, word, or phrase means something to you, you have heard it before and you know what it refers to.","ex":{"en":"'Oh, Gairdner,' he said, as if that meant something to him","cn":"“哦，盖尔德纳，”他说道，好像他听说过这个名字。"}},{"pos":"PHRASE 短语","cn":"出于好意;怀有善意","en":"If you say that someone means well, you mean they are trying to be kind and helpful, even though they might be causing someone problems or upsetting them.","ex":{"en":"I know you mean well, but I can manage by myself.","cn":"我明白您的好意，不过我自己能行。"}},{"pos":"PHRASE 短语","cn":"(疑问句中用于询问对方自己的理解是否正确)你是说","en":"You use 'you mean' in a question to check that you have understood what someone has said.","ex":{"en":"What accident? You mean Christina's?","cn":"哪次事故？你是说克里斯蒂娜的那次？"}},{"pos":"See also:","cn":"","en":"→see: ; →see: ; →see: ;"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吝啬的;小气的","en":"If you describe someone as mean, you are being critical of them because they are unwilling to spend much money or to use very much of a particular thing.","ex":{"en":"Don't be mean with fabric, otherwise curtains will end up looking skimpy.","cn":"别这么吝啬布料，不然做出来的窗帘会显得特寒酸。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数目）微薄的，少得可怜的","en":"If you describe an amount as mean, you are saying that it is very small.","ex":{"en":"...the meanest grant possible from the local council.","cn":"从地方委员会可能获得的微乎其微的拨款"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不友好的;刻薄的","en":"If someone is being mean, they are being unkind to another person, for example by not allowing them to do something.","ex":{"en":"The little girls had locked themselves in upstairs because Mack had been mean to them","cn":"小姑娘们把自己锁在楼上，因为麦克对她们很刻薄。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（指人或动物）脾气极坏的，残忍的","en":"If you describe a person or animal as mean, you are saying that they are very bad-tempered and cruel.","ex":{"en":"...the meanest fighter in the world.","cn":"世界上最残忍的斗士"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方）简陋的，破旧的","en":"If you describe a place as mean, you think that it looks poor and dirty.","ex":{"en":"He was raised on the mean streets of the central market district of Panama City.","cn":"他从小在巴拿马城中心闹市区的穷街陋巷里长大。"}},{"pos":"ADJ 形容词","cn":"在行的;熟练的;拿手的","en":"You can use mean in expressions such as 'He plays a mean trumpet' and 'She mixes a mean cocktail' to indicate that someone does something extremely well.","ex":{"en":"He cooks a mean salmon","cn":"他烧鲑鱼的水平一流。"}},{"pos":"PHRASE 短语","cn":"高水平的;上乘的;优秀的","en":"You can use no mean in expressions such as 'no mean writer' and 'no mean golfer' to indicate that someone does something well.","ex":{"en":"She was no mean performer on a variety of other instruments","cn":"许多别的乐器她也演奏得相当出色。"}},{"pos":"PHRASE 短语","cn":"了不起的;令人自豪的","en":"You can use no mean in expressions such as 'no mean achievement' and 'no mean task' to indicate that someone has done something they deserve to be proud of.","ex":{"en":"To destroy 121 enemy aircraft is no mean record","cn":"歼灭121架敌机是一个了不起的纪录。"}},{"pos":"N-SING 单数名词","cn":"平均数;平均值","en":"The mean is a number that is the average of a set of numbers.","ex":{"en":"Take a hundred and twenty values and calculate the mean.","cn":"取120个值计算平均数。"}}]},"examples":[{"en":"I'm feeling very guilty — I've been meaning to call my parents for days, but still haven't got around to it.","cn":"我感到非常内疚，几天来我一直打算给父母打电话，但还是没机会打。"},{"en":"$20 means a lot (= represents a lot of money) when you live on $100 a week.","cn":"当你每周就靠 100 元维持生活时，20 元可是个大数目。"}]},"meek":{"media":{"uk":"media/uk/meek__gb_1.mp3","us":"media/us/meek__us_1.mp3"},"oxford":{"phon":"miːk","pos":"adjective","senses":[{"en":"quiet, gentle, and always ready to do what other people want without expressing your own opinion","cn":"温顺的；谦恭的；驯服的","ex":{"en":"They called her Miss Mouse because she was so meek and mild.","cn":"他们称她为“鼠小姐”，因为她总是那么懦弱温和。"}},{"en":"people who are meek","cn":"温顺的人；谦恭的人","g":"[plural]","ex":{"en":"Blessed are the meek: for they shall inherit the earth.","cn":"温柔的人有福了，因为他们必承受土地。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"温顺的;顺从的","en":"If you describe a person as meek, you think that they are gentle and quiet, and likely to do what other people say.","ex":{"en":"He was a meek, mild-mannered fellow.","cn":"他是一个温顺随和的人。"}}]},"examples":[{"en":"They called her Miss Mouse because she was so meek and mild.","cn":"他们称她为“鼠小姐”，因为她总是那么懦弱谦和。"},{"en":"He meekly did as he was told.","cn":"他温顺地听从吩咐。"}]},"meet":{"media":{"uk":"media/uk/meet__gb_1.mp3","us":"media/us/meet__us_1.mp3"},"oxford":{"phon":"miːt","pos":"verb","senses":[{"en":"to be in the same place as somebody by chance and talk to them","cn":"相遇；相逢；遇见","g":"[intransitive, transitive, no passive]","sc":"by chance","ex":{"en":"Maybe we'll meet again some time.","cn":"说不定我们什么时候还会再见面。"}},{"en":"to come together formally in order to discuss something","cn":"开会；会晤","g":"[intransitive, transitive, no passive]","sc":"by arrangement","ex":{"en":"The committee meets on Fridays.","cn":"委员会每周五开会。"}},{"en":"to come together socially after you have arranged it","cn":"（与…）会面；集合","g":"[intransitive, transitive, no passive]","sc":"by arrangement","ex":{"en":"The town needs a space where young people can meet.","cn":"这个小镇需要一个年轻人可以聚会的空间。"}},{"en":"to go to a place and wait there for a particular person or thing to arrive","cn":"迎接","g":"[transitive]","sc":"by arrangement","ex":{"en":"Will you meet me at the airport?","cn":"你到机场接我好吗？"}},{"en":"to see and know somebody for the first time; to be introduced to somebody","cn":"相识；结识；被引见介绍（给某人）","g":"[intransitive, transitive, no passive]","lab":"especially British English","sc":"for the first time","ex":{"en":"I don't think we've met.","cn":"我想我们没见过面吧。"}},{"en":"to do or satisfy what is needed or what somebody asks for","cn":"满足；使满意","g":"[transitive]","sc":"satisfy","ex":{"en":"How can we best meet the needs of all the different groups?","cn":"我们如何才能最好地满足各个群体的需要呢？"}},{"en":"to play, fight, etc. together as opponents in a competition","cn":"遭遇；交锋","g":"[intransitive, transitive, no passive]","sc":"in contest","ex":{"en":"Smith and Jones met in last year's final.","cn":"史密斯和琼斯在去年的决赛中相遇。"}},{"en":"to experience something, often something unpleasant","cn":"经历（常指不愉快的事）","g":"[transitive]","sc":"experience something","ex":{"en":"Others have met similar problems.","cn":"其他人遇到过同样的问题。"}},{"en":"to be received or treated by somebody in a particular way","cn":"遭遇（某事）；受到某种对待","sc":"experience something","ex":{"en":"The announcement was met by loud boos from fans.","cn":"这一宣布遭到了球迷的大声嘘声。"}},{"en":"to touch something; to join","cn":"接触（某物）；连接","g":"[intransitive, transitive]","sc":"touch/join","ex":{"en":"The curtains don't meet in the middle.","cn":"这窗帘中间合不拢。"}},{"en":"to pay something","cn":"支付；偿付","g":"[transitive]","sc":"pay","ex":{"en":"The cost will be met by the company.","cn":"费用将由公司支付。"}},{"en":"a sports competition","cn":"体育比赛；运动会","lab":"especially North American English","ex":{"en":"a track meet","cn":"径赛运动会"},"pos":"noun"},{"en":"an event at which horse riders and dogs meet to go hunting. Fox hunting with dogs is now illegal in the UK but people still ride out with dogs following a scent trail, without an actual fox.","cn":"猎狐（如今在英国用狗猎狐属非法行为，但人们仍会携狗进行娱乐性质的气味追踪活动）","lab":"British English","pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"碰到;遇见","en":"If you meet someone, you happen to be in the same place as them and start talking to them. You may know the other person, but be surprised to see them, or you may not know them at all.","ex":{"en":"I have just met the man I want to spend the rest of my life with","cn":"我刚刚遇到了我想与之共度余生的男人。"}},{"pos":"V-RECIP 相互动词","cn":"(约定在某处)相会，碰头","en":"If two or more people meet, they go to the same place, which they have earlier arranged to do, so that they can talk or do something together.","ex":{"en":"We could meet for a drink after work","cn":"下班后我们可以见面喝上一杯。"}},{"pos":"VERB 动词","cn":"被引见给;认识;结识","en":"If you meet someone, you are introduced to them and begin talking to them and getting to know them.","ex":{"en":"Hey, Terry, come and meet my Dad.","cn":"嗨，特里，过来认识一下我爸爸。"}},{"pos":"VERB 动词","cn":"（初次）见面;认识;结识","en":"You use meet in expressions such as 'Pleased to meet you' and 'Nice to have met you' when you want to politely say hello or goodbye to someone you have just met for the first time.","ex":{"en":"'Jennifer,' Miss Mallory said, 'this is Leigh Van-Voreen.' — 'Pleased to meet you,' Jennifer said","cn":"“珍妮弗，”马洛里小姐说，“这位是利·范沃林。”——“见到您很高兴，”珍妮弗说。"}},{"pos":"VERB 动词","cn":"(到火车站、飞机场或公共汽车站)迎接","en":"If you meet someone off their train, plane, or bus, you go to the station, airport, or bus stop in order to be there when they arrive.","ex":{"en":"Mama met me at the station","cn":"妈妈在车站接我。"}},{"pos":"VERB 动词","cn":"会晤;开会","en":"When a group of people such as a committee meet, they gather together for a particular purpose.","ex":{"en":"Officials from the two countries will meet again soon to resume negotiations","cn":"两国官员不久将再度会晤以重启谈判。"}},{"pos":"VERB 动词","cn":"(与…)会晤","en":"If you meet with someone, you have a meeting with them.","ex":{"en":"Most of the lawmakers who met with the president yesterday said they backed the mission.","cn":"大多数昨天与总统会晤的立法者说他们支持这个行动。"}},{"pos":"V-ERG 及物/不及物动词","cn":"遭到;遇到;获得","en":"If something such as a suggestion, proposal, or new book meets with or is met with a particular reaction, it gets that reaction from people.","ex":{"en":"The idea met with a cool response from various quarters","cn":"这个想法遭到了各方人士的冷遇。"}},{"pos":"VERB 动词","cn":"满足;达到","en":"If something meets a need, requirement, or condition, it is good enough to do what is required.","ex":{"en":"The current arrangements for the care of severely mentally ill people are inadequate to meet their needs","cn":"目前对严重精神病患者的护理安排不足以满足他们的需要。"}},{"pos":"VERB 动词","cn":"对付;应对;克服","en":"If you meet something such as a problem or challenge, you deal with it satisfactorily or do what is required.","ex":{"en":"British manufacturing failed to meet the crisis of the 1970s","cn":"英国制造业未能经受住20世纪70年代危机的考验。"}},{"pos":"VERB 动词","cn":"偿付;支付","en":"If you meet the cost of something, you provide the money that is needed for it.","ex":{"en":"The government said it will help meet some of the cost of the damage","cn":"政府说将帮助支付损害造成的部分费用。"}},{"pos":"VERB 动词","cn":"碰上，遇到，遭遇(情况、态度、问题等)","en":"If you meet a situation, attitude, or problem, you experience it or become aware of it.","ex":{"en":"I honestly don't know how I will react the next time I meet a potentially dangerous situation","cn":"我真不知道下次再碰上有潜在危险的情况时会作何反应。"}},{"pos":"VERB 动词","cn":"获得(成功);遭到(失败)","en":"You can say that someone meets with success or failure when they are successful or unsuccessful.","ex":{"en":"Attempts to find civilian volunteers have met with embarrassing failure","cn":"寻找平民志愿者的种种尝试都遭遇了令人难堪的失败。"}},{"pos":"V-RECIP 相互动词","cn":"和…接触;与…相碰","en":"When a moving object meets another object, it hits or touches it.","ex":{"en":"You sense the stresses in the hull each time the keel meets the ground","cn":"每次龙骨触地的时候你都能感受到船体所受的压力。"}},{"pos":"V-RECIP 相互动词","cn":"(目光)接触,相遇","en":"If your eyes meet someone else's, you both look at each other at the same time.","ex":{"en":"Nina's eyes met her sisters' across the table","cn":"尼娜与桌子对面的姐妹们目光相遇。"}},{"pos":"V-RECIP 相互动词","cn":"(两片区域,尤指两片陆地或海洋)相接，汇合,相邻","en":"If two areas meet, especially two areas of land or sea, they are next to one another.","ex":{"en":"It is one of the rare places in the world where the desert meets the sea.","cn":"世界上沙漠与大海相接的地方非常少见，这里就是一处。"}},{"pos":"V-RECIP 相互动词","cn":"(两条线)相交，交叉","en":"The place where two lines meet is the place where they join together.","ex":{"en":"Parallel lines will never meet no matter how far extended","cn":"无论延伸多长，平行线永不相交。"}},{"pos":"V-RECIP 相互动词","cn":"(两个运动员、球队或军队)比赛,较量,交锋","en":"If two sportsmen, teams, or armies meet, they compete or fight against one another.","ex":{"en":"The two women will meet tomorrow in the final","cn":"这两位女选手将在明天的决赛里决一胜负。"}},{"pos":"N-COUNT 可数名词","cn":"运动会","en":"A meet is an event in which athletes come to a particular place in order to take part in a race or races.","ex":{"en":"John Pennel became the first person to pole-vault 17 ft., at a meet in Miami, Florida.","cn":"约翰·佩内尔在佛罗里达迈阿密的一次运动会上成为撑竿越过17英尺的第一人。"}},{"pos":"N-COUNT 可数名词","cn":"(猎狐前猎人和猎犬的)集合","en":"A meet is when riders and dogs gather somewhere before they set off on a fox hunt."},{"pos":"PHRASE 短语","cn":"迎着(或直视)(某人的)目光","en":"If you do not meet someone's eyes or meet someone's gaze, you do not look at them although they are looking at you, for example because you are ashamed.","ex":{"en":"He hesitated, then shook his head, refusing to meet her eyes.","cn":"他犹豫起来，然后摇摇头，避开了她的目光。"}},{"pos":"PHRASE 短语","cn":"（尤指因暴力或蹊跷）死去","en":"If someone meets their death or meets their end, they die, especially in a violent or suspicious way.","ex":{"en":"Jacob Sinclair met his death at the hands of a soldier","cn":"雅各布·辛克莱在一名士兵的手里送了命。"}},{"pos":"","cn":"","en":"to make ends meet→see: ; there's more to this than meets the eye→see: ; to meet someone's eyes→see: ; to meet someone halfway→see: ; to meet your match→see: ;"},{"pos":"","cn":"","en":"相关词组：meet up"}]},"examples":[{"en":"Until these conditions are met we cannot proceed with the sale.","cn":"除非这些条件得到满足，否则我们不能继续这项交易。"},{"en":"How can we best meet the needs of all the different groups?","cn":"我们怎样才能最好地满足各种人的需要呢？"}]},"mechanisms":{"oxford":{"phon":"ˈmekənɪzəm","pos":"noun","senses":[{"en":"a set of moving parts in a machine that performs a task","cn":"机械装置；机件"},{"en":"a method or a system for achieving sth","cn":"方法；机制"}]},"media":{"uk":"media/uk/mechanism__gb_1.mp3","us":"media/us/mechanism__us_1.mp3"}},"meaningful":{"media":{"uk":"media/uk/meaningful__gb_1.mp3","us":"media/us/meaningful__us_1.mp3"},"oxford":{"phon":"ˈmiːnɪŋfl","pos":"adjective","senses":[{"en":"serious and important","cn":"严肃的；重要的；重大的","ex":{"en":"a meaningful relationship/discussion/experience","cn":"重要的关系／讨论／经历"}},{"en":"having a meaning that is easy to understand","cn":"意义明显的；易于理解的","ex":{"en":"These statistics are not very meaningful.","cn":"这些统计数字说明不了什么问题。"}},{"en":"intended to communicate or express something to somebody, without any words being spoken","cn":"意味深长的；意在言外的","lab":"less frequent","ex":{"en":"She gave me a meaningful look.","cn":"她意味深长地看了我一眼。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严肃的;重要的;有意义的","en":"If you describe something as meaningful, you mean that it is serious, important, or useful in some way.","ex":{"en":"She believes these talks will be the start of a constructive and meaningful dialogue","cn":"她认为这些谈话将是一次具有建设性的、有意义的对话的开端。"}},{"pos":"ADJ 形容词","cn":"（指眼神、姿势）意味深长的，意在言外的","en":"A meaningful look or gesture is one that is intended to express something, usually to a particular person, without anything being said.","ex":{"en":"Upon the utterance of this word, Dan and Harry exchanged a quick, meaningful look.","cn":"这句话一出口，丹和哈里马上交换了一个意味深长的眼神。"}}]},"examples":[{"en":"These statistics are not very meaningful.","cn":"这些统计数字说明不了什么问题。"},{"en":"She gave me a meaningful look.","cn":"她意味深长地看了我一眼。"}]},"metropolitan":{"oxford":{"phon":"ˌmetrəˈpɒlɪtən","pos":"adjective","senses":[{"en":"connected with a large or capital city","cn":"大城市的；大都会的","lab":"also North American English, informal，，","ex":{"en":"the New York metropolitan area","cn":"纽约都市区"}},{"en":"connected with a particular country rather than with the other regions of the world that the country controls","cn":"本土的","ex":{"en":"metropolitan France/Spain","cn":"法国／西班牙本土"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"大都会的;大都市的","en":"Metropolitan means belonging to or typical of a large busy city.","ex":{"en":"...the metropolitan district of Miami.","cn":"迈阿密的都市区"}},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(东正教和天主教的)大主教","en":"A metropolitan is an important priest in the Orthodox and Catholic Churches. He has authority over other priests and is in charge of a particular area.","ex":{"en":"...the Ukrainian Catholic representatives, Metropolitan Volodymyr and Bishop Sofron.","cn":"乌克兰的天主教代表——弗拉基米尔大主教和索夫龙主教"}}]},"media":{"uk":"media/uk/metropolitan__gb_1.mp3","us":"media/us/metropolitan__us_1.mp3"},"examples":[{"en":"metropolitan France/Spain","cn":"法国/西班牙本土"},{"en":"the New York metropolitan area","cn":"纽约都市区"}]},"measure":{"media":{"uk":"media/uk/measure__gb_1.mp3","us":"media/us/measure__us_1.mp3"},"oxford":{"phon":"ˈmeʒə(r)","pos":"verb","senses":[{"en":"to find the size, quantity, etc. of something in standard units","cn":"测量；度量","sc":"size/quantity","ex":{"en":"a device that measures the level of radiation in the atmosphere","cn":"测量大气中辐射强度的仪器"}},{"en":"to be a particular size, length, amount, etc.","cn":"（指尺寸、长短、数量等）量度为","sc":"size/quantity","ex":{"en":"The main bedroom measures 12ft by 15ft.","cn":"主卧室宽 12 英尺，长 15 英尺。"}},{"en":"to judge the importance, value or effect of something","cn":"估量，判定（重要性、价值或影响）","sc":"judge","ex":{"en":"It is difficult to measure the success of the campaign at this stage.","cn":"在现阶段还难以估量这场运动的成败。"}},{"en":"an official action that is done in order to achieve a particular aim","cn":"措施；方法","g":"[countable]","sc":"official action","ex":{"en":"safety/austerity measures","cn":"安全/紧缩措施"},"pos":"noun"},{"en":"a unit used for stating the size, quantity or degree of something; a system or a scale of these units","cn":"度量单位；计量标准","g":"[countable, uncountable]","sc":"unit of size/quantity","ex":{"en":"weights and measures","cn":"度量衡"},"pos":"noun"},{"en":"a standard quantity","cn":"标准量","g":"[countable]","sc":"unit of size/quantity","ex":{"en":"a generous measure of whisky","cn":"比标准量稍多一点的威士忌"},"pos":"noun"},{"en":"a way of judging or measuring something","cn":"判断；衡量","g":"[countable]","sc":"way of showing/judging","ex":{"en":"an accurate measure of ability","cn":"能力的准确评判"},"pos":"noun"},{"en":"a sign of the size or the strength of something","cn":"尺度；标准；程度","g":"[singular]","sc":"way of showing/judging","ex":{"en":"Sending flowers is a measure of how much you care.","cn":"送花能表明你有多关心。"},"pos":"noun"},{"en":"a particular amount of something, especially a fairly large amount","cn":"（一定的）量，程度","g":"[singular]","sc":"amount","ex":{"en":"A measure of technical knowledge is desirable in this job.","cn":"做这项工作最好多懂一些技术知识。"},"pos":"noun"},{"en":"an instrument such as a stick, a long tape or a container that is marked with standard units and is used for measuring","cn":"量器；计量工具","g":"[countable]","sc":"instrument for measuring","pos":"noun"},{"en":"a written suggestion, especially one for a new law made by the lawmakers of a state","cn":"（尤指州立法者的）提案，法案，议案","g":"[countable]","lab":"North American English","sc":"suggested new law","ex":{"en":"a motion to refer the measure to another committee","cn":"将提案提交给另一个委员会的动议"},"pos":"noun"},{"en":"one of the short sections of equal length that a piece of music is divided into, and the notes that are in it","cn":"（乐谱的）小节（音乐节拍单位）","g":"[countable]","lab":"British English usually","sc":"in music","ex":{"en":"The band began playing the opening measures.","cn":"乐队开始演奏开头几个小节。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"衡量；估量;评估;判定","en":"If you measure the quality, value, or effect of something, you discover or judge how great it is.","ex":{"en":"I continued to measure his progress against the charts in the doctor's office","cn":"我继续比照医生办公室里的图表来判断他病情的发展。"}},{"pos":"VERB 动词","cn":"测量;度量;计量","en":"If you measure a quantity that can be expressed in numbers, such as the length of something, you discover it using a particular instrument or device, for example a ruler.","ex":{"en":"Measure the length and width of the gap","cn":"测量一下这条缝隙的长与宽。"}},{"pos":"VERB 动词","cn":"距离(或长度、宽度、数量等)为…","en":"If something measures a particular length, width, or amount, that is its size or intensity, expressed in numbers.","ex":{"en":"The house is more than twenty metres long and measures six metres in width","cn":"这座房子长20多米，宽6米。"}},{"pos":"N-SING 单数名词","cn":"相当数量;一定程度","en":"A measure of a particular quality, feeling, or activity is a fairly large amount of it.","ex":{"en":"With the exception of Juan, each attained a measure of success","cn":"除了胡安之外，每个人都获得了相当大的成功。"}},{"pos":"N-SING 单数名词","cn":"（情形严重或发展到了一定程度的）体现，表现，标志","en":"If you say that one aspect of a situation is a measure of that situation, you mean that it shows that the situation is very serious or has developed to a very great extent.","ex":{"en":"It is a measure of their plight that few of them have anywhere to go to","cn":"他们几乎全都无处可归，看得出他们是陷入了困境。"}},{"pos":"N-COUNT 可数名词","cn":"措施;办法","en":"When someone, usually a government or other authority, takes measures to do something, they carry out particular actions in order to achieve a particular result.","ex":{"en":"The government warned that police would take tougher measures to contain the trouble","cn":"政府警告说，警方将采取更为强硬的措施来遏制动乱。"}},{"pos":"N-COUNT 可数名词","cn":"(标准量的)一杯(烈性酒)","en":"A measure of a strong alcoholic drink such as brandy or whisky is an amount of it in a glass. In pubs and bars, a measure is an official standard amount.","ex":{"en":"He poured himself another generous measure of malt.","cn":"他又为自己倒了满满一大杯麦芽威士忌。"}},{"pos":"N-COUNT 可数名词","cn":"(音乐的)小节","en":"In music, a measure is one of the several short parts of the same length into which a piece of music is divided."},{"pos":"PHRASE 短语","cn":"非常;极其","en":"If you say that something has changed or that it has affected you beyond measure, you are emphasizing that it has done this to a great extent.","ex":{"en":"Mankind's knowledge of the universe has increased beyond measure","cn":"人类对于宇宙的了解已经大为增加。"}},{"pos":"PHRASE 短语","cn":"附加地;除此之外地","en":"If you say that something is done for good measure, you mean that it is done in addition to a number of other things.","ex":{"en":"I repeated my question for good measure","cn":"另外，我重复了我的问题。"}},{"pos":"PHRASE 短语","cn":"了解;熟悉;估量…的能力/掂量出…的分量;摸清…的底细","en":"If you get or take the measure of someone or something, you discover what they are like, so that you are able to control them or deal with them. If you have the measure of someone or something, you have succeeded in doing this.","ex":{"en":"The governments of the industrialized world had failed to get the measure of the crisis","cn":"工业化国家的政府没能意识到这次危机的严重程度。"}},{"pos":"PHRASE 短语","cn":"在某种程度上/在很大程度上","en":"If something is true in some measure or in large measure, it is partly or mostly true.","ex":{"en":"Power is in some measure an act of will","cn":"权力在某种程度上是意志的表现。"}},{"pos":"","cn":"","en":"相关词组：measure out measure up"}]},"examples":[{"en":"The concert only lasted an hour, so we felt we were getting short measure.","cn":"音乐会仅仅持续了一个小时，让我们有一种缺斤少两的感觉。"},{"en":"After only one game, the chess champion had the measure of his young opponent.","cn":"仅仅一局过后，这位国际象棋冠军就摸清了年轻对手的实力。"}]},"met":{"media":{"uk":"media/uk/met__gb_2.mp3","us":"media/us/met__us_2.mp3"},"oxford":{"phon":"met","pos":"abbreviation","senses":[{"en":"meteorological","cn":"气象的；气象学的","ex":{"en":"the Met Office weather forecast service","cn":"国家气象局天气预报处"}}]},"examples":[{"en":"the Met Office weather forecast service","cn":"国家气象局天气预报处"}],"collins":{"senses":[{"pos":"","cn":"","en":"Met is the past tense and past participle of meet."}]}},"meal":{"media":{"uk":"media/uk/meal__gb_1.mp3","us":"media/us/meal__us_1.mp3"},"oxford":{"phon":"miːl","pos":"noun","senses":[{"en":"an occasion when people eat food, especially breakfast, lunch or dinner","cn":"早（或午、晚）餐；一顿饭","g":"[countable]","lab":"especially British English","ex":{"en":"Try not to eat between meals.","cn":"两餐之间尽量别吃东西。"}},{"en":"the food that is eaten at a meal","cn":"一餐所吃的食物","g":"[countable]","ex":{"en":"Enjoy your meal.","cn":"请用餐。"}},{"en":"grain that has been made into a powder, used as food for animals and for making flour","cn":"谷物粗粉（用作饲料或加工面粉）","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一餐;一顿饭","en":"A meal is an occasion when people sit down and eat, usually at a regular time.","ex":{"en":"She sat next to him throughout the meal","cn":"用餐时她一直坐在他身旁。"}},{"pos":"N-COUNT 可数名词","cn":"一餐所吃的食物","en":"A meal is the food you eat during a meal.","ex":{"en":"The waiter offered him red wine or white wine with his meal","cn":"侍者为他端上佐餐的红葡萄酒或者白葡萄酒。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（谷物的）粗磨粉","en":"Meal is a rough powder made of crushed grain. It is used to make flour or animal food."},{"pos":"PHRASE 短语","cn":"花费过多的时间或精力做…;对…小题大做","en":"If you think someone is taking more time and energy to do something than is necessary, you can say that they are making a meal of it.","ex":{"en":"Lawyers always make such a meal of the simplest little thing.","cn":"律师总是死抠细节。"}},{"pos":"PHRASE 短语","cn":"健康丰盛的一餐","en":"If you have a square meal, you have a large healthy meal."}]},"examples":[{"en":"What time do the kids have their tea?","cn":"孩子们什么时候用傍晚主餐？"},{"en":"Try not to eat between meals.","cn":"两餐之间尽量别吃东西。"}]},"metallic":{"media":{"uk":"media/uk/metallic__gb_1.mp3","us":"media/us/metallic__us_1.mp3"},"oxford":{"phon":"məˈtælɪk","pos":"adjective","senses":[{"en":"that looks, tastes or sounds like metal","cn":"金属般的；有金属味（或声音）的","ex":{"en":"metallic paint/colours/blue","cn":"有金属光泽的颜料／颜色／蓝色"}},{"en":"made of or containing metal","cn":"金属制的；含金属的","ex":{"en":"a metallic object","cn":"金属物品"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"金属撞击般的；叮当声的","en":"A metallic sound is like the sound of one piece of metal hitting another.","ex":{"en":"There was a metallic click and the gates swung open","cn":"随着一声金属碰击的咔嗒声，大门打开了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖厉刺耳的;难听的","en":"A metallic voice has a harsh unpleasant sound.","ex":{"en":"...that creaking metallic voice of hers.","cn":"她那尖厉刺耳的嗓音"}},{"pos":"ADJ 形容词","cn":"(涂料、颜色)有金属光泽的，金属般闪亮的","en":"Metallic paint or colours shine like metal.","ex":{"en":"He had painted all the wood with metallic silver paint","cn":"他给所有的木材都涂上了一层闪耀着金属光泽的银漆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"金属味的","en":"Something that tastes metallic has a bitter unpleasant taste.","ex":{"en":"There was a metallic taste at the back of his throat.","cn":"他喉咙深处有一股金属味儿。"}},{"pos":"ADJ 形容词","cn":"含金属的；金属制的","en":"Metallic means consisting entirely or partly of metal.","ex":{"en":"Even the smallest metallic object, whether a nail file or cigarette lighter, is immediately confiscated","cn":"即便是最小的金属物品，不管是指甲锉刀还是打火机，都会马上被没收。"}}]},"examples":[{"en":"a metallic voice (= that sounds unpleasant)","cn":"尖厉刺耳的声音"},{"en":"metallic paint/colours/blue","cn":"有金属光泽的颜料/颜色/蓝色"}]},"memory":{"media":{"uk":"media/uk/memory__gb_1.mp3","us":"media/us/memory__us_1.mp3"},"oxford":{"phon":"ˈmeməri","pos":"noun","senses":[{"en":"your ability to remember things","cn":"记忆力；记性","g":"[countable, uncountable]","sc":"ability to remember","ex":{"en":"I have a bad memory for names.","cn":"我不善于记名字。"}},{"en":"the period of time that a person or group of people is able to remember events","cn":"记忆所及的时期；回忆所及的范围","g":"[uncountable]","sc":"ability to remember","ex":{"en":"There hasn’t been peace in the country in my memory.","cn":"在我的记忆里，这个国家从没太平过。"}},{"en":"a thought of something that you remember from the past","cn":"回忆；记忆","g":"[countable]","sc":"something you remember","ex":{"en":"Her poems are often based on childhood memories.","cn":"她的诗常常取材于童年回忆。"}},{"en":"what is remembered about somebody after they have died","cn":"对死者的记忆","g":"[uncountable]","lab":"formal","sc":"something you remember","ex":{"en":"Her memory lives on (= we still remember her).","cn":"我们永远怀念她。"}},{"en":"the part of a computer where information is stored; the amount of space in a computer for storing information","cn":"存储器；内存；记忆体","g":"[countable, uncountable]","sc":"computing","ex":{"en":"32 gigabytes of memory","cn":"32 GB 内存"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"记忆力;记性","en":"Your memory is your ability to remember things.","ex":{"en":"All the details of the meeting are fresh in my memory","cn":"我对会议的所有细节都记忆犹新。"}},{"pos":"N-COUNT 可数名词","cn":"记忆;记忆中的事物;回忆","en":"A memory is something that you remember from the past.","ex":{"en":"She cannot bear to watch the film because of the bad memories it brings back","cn":"她看不了那部电影，因为它会勾起一些痛苦的回忆。"}},{"pos":"N-COUNT 可数名词","cn":"存储器;内存","en":"A computer's memory is the part of the computer where information is stored, especially for a short time before it is transferred to disks or magnetic tapes.","ex":{"en":"The data are stored in the computer's memory.","cn":"资料存在计算机内存里。"}},{"pos":"N-SING 单数名词","cn":"(对死者的)怀念，记忆","en":"If you talk about the memory of someone who has died, especially someone who was loved or respected, you are referring to the thoughts, actions, and ceremonies by which they are remembered.","ex":{"en":"She remained devoted to his memory","cn":"她对他仍十分怀念。"}},{"pos":"PHRASE 短语","cn":"凭记忆(诵诗、奏曲等)","en":"If you do something from memory, for example speak the words of a poem or play a piece of music, you do it without looking at it, because you know it very well.","ex":{"en":"Many members of the church sang from memory","cn":"许多教徒都是凭记忆唱颂歌。"}},{"pos":"PHRASE 短语","cn":"在人们的记忆中（最…的事情）","en":"If you say that something is, for example, the best, worst, or first thing of its kind in living memory, you are emphasizing that it is the only thing of that kind that people can remember.","ex":{"en":"The floods are the worst in living memory","cn":"那次洪水是人们记忆中最严重的一次。"}},{"pos":"PHRASE 短语","cn":"失去记忆力;失忆","en":"If you lose your memory, you forget things that you used to know.","ex":{"en":"His illness caused him to lose his memory.","cn":"疾病使他失忆了。"}},{"pos":"","cn":"","en":"to commit something to memory→see: ;"}]},"examples":[{"en":"He founded the charity in memory of his late wife.","cn":"他创办了这一慈善事业以纪念他已故的妻子。"},{"en":"It was the worst storm in recent memory.","cn":"最近能记得的风暴中，这是最厉害的一次。"}]},"mechanically":{"oxford":{"phon":"məˈkænɪkli","pos":"adverb","senses":[{"en":"by power from an engine","cn":"通过发动机的动力","ex":{"en":"a mechanically powered vehicle","cn":"机动车"}},{"en":"using a machine or an engine","cn":"使用机器或发动机","ex":{"en":"The patient was mechanically ventilated.","cn":"患者接受机械通气。"}},{"en":"in a way that is connected with mechanics (= the science of movement and force)","cn":"在某种程度上与力学有关","ex":{"en":"The theory was flawed electrically, mechanically and energetically.","cn":"该理论在电气、机械和能量方面都存在缺陷。"}},{"en":"without thinking, like a machine","cn":"没有思想，像机器一样","ex":{"en":"She spoke mechanically, as if thinking of something else.","cn":"她机械地说着话，仿佛在想着什么别的事情。"}},{"en":"with a good understanding of how machines work","cn":"对机器如何工作有很好的理解","ex":{"en":"He's always been mechanically minded.","cn":"他对机械方面一直很在行。"}}]},"media":{"uk":"media/uk/mechanically__gb_1.mp3","us":"media/us/mechanically__us_1.mp3"},"examples":[{"en":"She spoke mechanically, as if thinking of something else.","cn":"她机械地说着话，彷佛在想着什么别的事情。"},{"en":"He's always been mechanically minded.","cn":"他思想一向很僵化。"}]},"medium-sized":{"oxford":{"phon":"ˈmiːdiəm saɪzd","pos":"adjective","senses":[{"en":"of average size","cn":"中等大小的；中型的；中号的","ex":{"en":"a medium-sized saucepan","cn":"中号的锅"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"中号的;中型的;中等大小的","en":"Medium-sized means neither large nor small, but approximately half way between the two.","ex":{"en":"...a medium-sized saucepan.","cn":"中号炖锅"}}]},"media":{"uk":"media/uk/medium_sized_1_gb_1.mp3","us":"media/us/medium_sized_1_us_1.mp3"},"examples":[{"en":"a medium-sized saucepan","cn":"中号的锅"},{"en":"a medium-sized business","cn":"中等大小的公司"}]},"means":{"media":{"uk":"media/uk/means__gb_1.mp3","us":"media/us/means__us_1.mp3"},"oxford":{"phon":"miːnz","pos":"noun","senses":[{"en":"an action, an object or a system by which a result is achieved; a way of achieving or doing something","cn":"方式；方法；途径","g":"[countable]","ex":{"en":"Email is a highly effective means of communication.","cn":"电邮是一种高效的交流方式。"}},{"en":"the money that a person has","cn":"财富；钱财","g":"[plural]","ex":{"en":"a man of means (= a rich man)","cn":"有钱人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方法;手段;工具(means 用于此意时单复数同形)","en":"A means of doing something is a method, instrument, or process which can be used to do it. Means is both the singular and the plural form for this use.","ex":{"en":"The move is a means to fight crime","cn":"采取这项举措是为了打击犯罪。"}},{"pos":"N-PLURAL 复数名词","cn":"收入;财富;金钱","en":"You can refer to the money that someone has as their means .","ex":{"en":"...a person of means","cn":"富人"}},{"pos":"PHRASE 短语","cn":"超出财力；入不敷出/在财力之内；量入为出","en":"If someone is living beyond their means, they are spending more money than they can afford. If someone is living within their means, they are not spending more money than they can afford.","ex":{"en":"The more gifts she received, the more she craved, until he was living beyond his means","cn":"得到的礼物越多，她的胃口就越大，直到他捉襟见肘为止。"}},{"pos":"PREP-PHRASE 短语介词","cn":"用;以;通过","en":"If you do something by means of a particular method, instrument, or process, you do it using that method, instrument, or process.","ex":{"en":"This is a two year course taught by means of lectures and seminars","cn":"本课程为期两年，授课形式为讲座与研讨。"}},{"pos":"CONVENTION 惯用语","cn":"当然可以;完全可以","en":"You can say 'by all means' to tell someone that you are very willing to allow them to do something.","ex":{"en":"'Can I come and have a look at your house?' — 'Yes by all means'.","cn":"“我可以过来看看你的房子吗？”“当然可以。”"}},{"pos":"PHRASE 短语","cn":"决不;丝毫不;一点儿也不","en":"You use expressions such as 'by no means', 'not by any means', and 'by no manner of means' to emphasize that something is not true.","ex":{"en":"This is by no means out of the ordinary","cn":"这丝毫不足为奇。"}},{"pos":"PHRASE 短语","cn":"达到目的的手段","en":"If you say that something is a means to an end, you mean that it helps you to achieve what you want, although it may not be enjoyable or important itself.","ex":{"en":"We seem to have lost sight of the fact that marketing is only a means to an end.","cn":"我们似乎忽略了这样一个事实：营销只是达到目的的手段。"}}]},"examples":[{"en":"He doesn't particularly like the work but he sees it as a means to an end.","cn":"他不怎么喜欢这项工作，只是把它看作达到目的的手段而已。"},{"en":"We needed to get to London but we had no means of transport.","cn":"我们需要去伦敦，但却没有任何交通工具。"}]},"mechanic":{"media":{"uk":"media/uk/mechanic__gb_1.mp3","us":"media/us/mechanic__us_1.mp3","img":["media/ldoce/img/mechanic.jpg"]},"oxford":{"phon":"məˈkænɪk","pos":"noun","senses":[{"en":"a person whose job is repairing machines, especially the engines of vehicles","cn":"机械师；机械修理工；技工","g":"[countable]","ex":{"en":"a car/motor mechanic","cn":"汽车修理工"}},{"en":"the science of movement and force","cn":"力学","g":"[uncountable]"},{"en":"the practical study of machines","cn":"机械学","g":"[uncountable]","ex":{"en":"the school’s car maintenance department where students learn basic mechanics","cn":"该校学生可以学习基础机械学的汽车保养系"}},{"en":"the working parts of a machine","cn":"机械部件；运转部件","ex":{"en":"He looks at the mechanics of a car before the bodywork.","cn":"他先看汽车的机械结构，然后看车身。"}},{"en":"the way something works or is done","cn":"方法；手段","g":"[plural]","ex":{"en":"The exact mechanics of how payment will be made will be decided later.","cn":"确切的付款方法以后再作决定。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指修理汽车的）技工，机修工，修理工","en":"A mechanic is someone whose job is to repair and maintain machines and engines, especially car engines.","ex":{"en":"If you smell gas fumes or burning, take the car to your mechanic","cn":"如果你闻见汽油冒烟或燃烧的异味，应把车送修。"}},{"pos":"N-PLURAL 复数名词","cn":"（过程、系统、动作等）运作方式;(具体的)方法，技巧","en":"The mechanics of a process, system, or activity are the way in which it works or the way in which it is done.","ex":{"en":"What are the mechanics of this new process?","cn":"这一新工序如何操作？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"力学;机械学","en":"Mechanics is the part of physics that deals with the natural forces that act on moving or stationary objects.","ex":{"en":"...the other great theory of 20th-century physics, quantum mechanics","cn":"20世纪物理学的另一个伟大理论——量子力学"}}]},"examples":[{"en":"the school's car maintenance department where students learn basic mechanics","cn":"该校学生可以学习基础机械学的汽车保养系"},{"en":"The exact mechanics of how payment will be made will be decided later.","cn":"确切的付款方法以后再作决定。"}]},"membership":{"oxford":{"phon":"ˈmembəʃɪp","pos":"noun","senses":[{"en":"the state of being a member of a group, a club, an organization, etc.","cn":"会员资格；成员资格","g":"[uncountable, countable]","lab":"British English","ex":{"en":"Who is eligible to apply for membership of the association?","cn":"谁有资格申请加入这个协会？"}},{"en":"the members, or the number of members, of a group, a club, an organization, etc.","cn":"（统称）会员，成员；会员人数；成员数","g":"[countable + singular or plural verb]","ex":{"en":"The membership has/have not yet voted.","cn":"会员还没有进行投票。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"会员身份;成员资格","en":"Membership of an organization is the state of being a member of it.","ex":{"en":"The country has also been granted membership of the World Trade Organisation","cn":"这个国家也被准予加入世界贸易组织。"}},{"pos":"N-VAR-COLL 可变集合名词","cn":"全体会员(或成员);全体会员(或成员)人数","en":"The membership of an organization is the people who belong to it, or the number of people who belong to it.","ex":{"en":"The European Builders Confederation has a membership of over 350,000 building companies.","cn":"欧洲建筑商联合会拥有逾35万家建筑公司会员。"}}]},"media":{"uk":"media/uk/membership__gb_1.mp3","us":"media/us/membership__us_1.mp3"},"examples":[{"en":"The club has a membership of more than 500.","cn":"俱乐部的会员人数超过了 500 名。"},{"en":"Who is eligible to apply for membership of the association?","cn":"谁有资格申请加入这个协会？"}]},"mention":{"media":{"uk":"media/uk/mention__gb_1.mp3","us":"media/us/mention__us_1.mp3"},"oxford":{"phon":"ˈmenʃn","pos":"verb","senses":[{"en":"to write or speak about something/somebody, especially without giving much information","cn":"提到；写到；说到","ex":{"en":"Sorry, I won't mention it again.","cn":"对不起，我再也不提它了。"}},{"en":"to refer to somebody/something as being interesting, especially as a possible candidate for a job or position","cn":"推荐；引介；提名","ex":{"en":"His name has been mentioned as a future MP.","cn":"有人提到他，认为他将来可以当下院议员。"}},{"en":"an act of referring to somebody/something in speech or writing","cn":"提及；说起；写上一笔","ex":{"en":"He made no mention of her work.","cn":"他根本没提她的工作。"},"pos":"noun"},{"en":"an act of acknowledging somebody/something as deserving praise","cn":"提名表扬","ex":{"en":"Phil deserves (a) special mention for all the help he gave us.","cn":"菲尔对我们的帮助很大，理应特别提一提。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(简短地)谈及，说起，提到","en":"If you mention something, you say something about it, usually briefly.","ex":{"en":"She did not mention her mother's absence","cn":"她并没有说起她母亲不在场的事。"}},{"pos":"N-VAR 可变名词","cn":"提及;论及","en":"A mention is a reference to something or someone.","ex":{"en":"The statement made no mention of government casualties","cn":"声明里没有提及政府方面的伤亡情况。"}},{"pos":"VERB 动词","cn":"（在文章中）提到，谈及(某人的名字)","en":"If someone is mentioned in writing, a reference is made to them by name, often to criticize or praise something that they have done.","ex":{"en":"I was absolutely outraged that I could be even mentioned in an article of this kind","cn":"我大为恼火，我的名字居然出现在这种文章里面。"}},{"pos":"VERB 动词","cn":"提名;推荐","en":"If someone is mentioned as a candidate for something such as a job, it is suggested that they might become a candidate.","ex":{"en":"His appointment is a complete surprise — he has never been mentioned as a front runner","cn":"他的任命完全出人意料——他从来都不是呼声最高的候选人。"}},{"pos":"N-VAR 可变名词","cn":"提名表扬","en":"A special or honourable mention is formal praise that is given for an achievement that is very good, although not usually the best of its kind.","ex":{"en":"So many people have helped me with this book that it is hard to pick out the few for special mention.","cn":"帮助我完成本书的人数太多，难以从中选出几位特别致谢。"}},{"pos":"CONVENTION 惯用语","cn":"别客气;不用谢","en":"People sometimes say 'don't mention it' as a polite reply to someone who has just thanked them for doing something.","ex":{"en":"'Thank you very much.' — 'Don't mention it.'","cn":"“非常感谢！”——“别客气。”"}},{"pos":"PHRASE 短语","cn":"不用说;更不必说","en":"You use not to mention when you want to add extra information which emphasizes the point that you are making.","ex":{"en":"The audience, not to mention the bewildered cast, were not amused","cn":"观众们并没有觉得好笑，更不用说那些一头雾水的演员了。"}},{"pos":"","cn":"","en":"to be mentioned in dispatches→see: ;"}]},"examples":[{"en":"He has two big houses in this country, not to mention his villa in France.","cn":"他在这个国家有两座大房子，更别提他在法国的别墅了。"},{"en":"Now that you mention it, she did seem to be in a strange mood.","cn":"既然你说到这事儿，她确实好像情绪不大对。"}]},"medium":{"media":{"uk":"media/uk/medium__gb_1.mp3","us":"media/us/medium__us_1.mp3"},"oxford":{"phon":"ˈmiːdiəm","pos":"adjective","senses":[{"en":"in the middle between a larger and smaller size, amount, length, temperature, etc.","cn":"中等的；中号的","ex":{"en":"There are three sizes—small, medium and large.","cn":"有三种尺寸，分别是小号、中号和大号。"}},{"en":"a way of communicating information, etc. to people","cn":"（传播信息等的）媒介，手段，方法","ex":{"en":"the medium of radio/television","cn":"广播／电视媒介"},"pos":"noun"},{"en":"something that is used for a particular purpose","cn":"手段；工具；方法","ex":{"en":"English is the medium of instruction (= the language used to teach other subjects).","cn":"用英语进行教学。"},"pos":"noun"},{"en":"the material used for storing computer files, such as on magnetic tape or discs","cn":"存储介质（如磁带或光盘）","lab":"computing","ex":{"en":"Copy files to and from the device as you would with any other storage medium.","cn":"就像使用任何其他存储介质一样，将文件复制到设备或从设备复制文件。"},"pos":"noun"},{"en":"the material or the form that an artist, a writer or a musician uses","cn":"（文艺创作中使用的）材料，形式","ex":{"en":"the medium of paint/poetry/drama","cn":"绘画／诗歌／戏剧的表现手法"},"pos":"noun"},{"en":"a substance that something exists or grows in or that it travels through","cn":"介质；培养基；环境","lab":"biology","ex":{"en":"The bacteria were growing in a sugar medium.","cn":"细菌在糖基中生长。"},"pos":"noun"},{"en":"a person who claims to be able to communicate with the spirits of dead people","cn":"通灵的人；灵媒；巫师","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"中等的;中间的;中号的","en":"If something is of medium size, it is neither large nor small, but approximately half way between the two.","ex":{"en":"A medium dose produces severe nausea within hours","cn":"中等剂量几小时之内会引发严重的恶心。"}},{"pos":"ADJ 形容词","cn":"中间的;平均的","en":"You use medium to describe something which is average in degree or amount, or approximately half way along a scale between two extremes.","ex":{"en":"Foods that contain only medium levels of sodium are bread, cakes, milk, butter and margarine.","cn":"含钠量仅为中等水平的食物有面包、蛋糕、牛奶、黄油和人造黄油。"}},{"pos":"COMB in COLOUR 与颜色词构成的词","cn":"(颜色)不深不浅的，适中的","en":"If something is of a medium colour, it is neither light nor dark, but approximately half way between the two.","ex":{"en":"Andrea has medium brown hair, grey eyes and very pale skin","cn":"安德烈娅有着深浅适中的棕发、灰色的眼睛和十分白皙的皮肤。"}},{"pos":"N-COUNT 可数名词","cn":"(表现)方式;(交流)手段","en":"A medium is a way or means of expressing your ideas or of communicating with people.","ex":{"en":"In Sierra Leone, English is used as the medium of instruction for all primary education","cn":"在塞拉利昂，基础教育阶段全部用英语授课。"}},{"pos":"N-COUNT 可数名词","cn":"媒介;介质;媒介物","en":"A medium is a substance or material which is used for a particular purpose or in order to produce a particular effect.","ex":{"en":"Blood is the medium in which oxygen is carried to all parts of the body","cn":"血液是将氧气输送到人体各个部位的媒介。"}},{"pos":"N-COUNT 可数名词","cn":"(自称能够在死者与生者之间传递信息的)巫师，灵媒","en":"A medium is a person who claims to be able to contact and speak to people who are dead, and to pass messages between them and people who are still alive."},{"pos":"PHRASE 短语","cn":"中庸之道;折中办法","en":"If you strike or find a happy medium between two extreme and opposite courses of action, you find a sensible way of behaving that is somewhere between the two extremes.","ex":{"en":"I still aim to strike a happy medium between producing football that's worth watching and getting results","cn":"我仍致力于打造这样一种球风——既具观赏性，又能得分，两全其美。"}}]},"examples":[{"en":"A T-shirt can be an excellent medium for getting your message across. * T","cn":"恤衫可以成为一种极好的表达信息的媒介。"},{"en":"There are three sizes — small, medium and large.","cn":"有三种尺寸 — 小号、中号和大号。"}]},"methodologically":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the set of methods and principles that you use when studying a particular subject or doing a particular kind of work","cn":""}]},"examples":[{"en":"We’ve been developing a new methodology for assessing new products.","cn":"","src":"ld"},{"en":"There are some differences in methodology between the two studies.","cn":"","src":"ld"}],"media":{"uk":"media/uk/methodologically__gb_1.mp3","us":"media/us/methodologically__us_1.mp3"},"oxford":{"phon":"ˌmeθədəˈlɒdʒɪkli","pos":"adverb","senses":[{"en":"in a way that involves a set of methods and principles that are used to perform a particular activity","cn":"（从事某一活动的）方法，原则","ex":{"en":"The experiment was methodologically sound, but we need to repeat it to be sure the results are correct.","cn":"这个实验在方法上是合理的，但我们需要重复它以确保结果是正确的。"}}]}},"mediocrity":{"media":{"uk":"media/uk/mediocrity__gb_1.mp3","us":"media/us/mediocrity__us_1.mp3"},"oxford":{"phon":"ˌmiːdiˈɒkrəti","pos":"noun","senses":[{"en":"the fact of being average or not very good","cn":"平庸；普通；平常","g":"[uncountable]","ex":{"en":"His acting career started brilliantly, then sank into mediocrity.","cn":"他的演艺生涯开场时轰轰烈烈，然后就变得庸庸碌碌。"}},{"en":"a person who is not very good at something","cn":"平庸之人；碌碌无为者","g":"[countable]","ex":{"en":"a brilliant leader, surrounded by mediocrities","cn":"周围全是些庸才的杰出领导"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"平庸;平凡;普通","en":"If you refer to the mediocrity of something, you mean that it is of average quality but you think it should be better.","ex":{"en":"...the mediocrity of most contemporary literature","cn":"大多数当代文学作品的平庸"}},{"pos":"N-COUNT 可数名词","cn":"庸人;平庸之辈","en":"If you refer to someone as a mediocrity, you think that they are not very good at what they do.","ex":{"en":"Surrounded by mediocrities, he can seem a towering intellectual.","cn":"在周围一群泛泛之辈的衬托之下，他就像一个鹤立鸡群的智者。"}}]},"examples":[{"en":"His acting career started brilliantly, then sank into mediocrity.","cn":"他的演艺生涯开场时轰轰烈烈，然后就变得庸庸碌碌。"},{"en":"a brilliant leader, surrounded by mediocrities","cn":"周围全是些庸才的杰出领导"}]},"medicines":{"oxford":{"phon":"ˈmedsn","pos":"noun","senses":[{"en":"the study and treatment of diseases and injuries","cn":"医学"},{"en":"a substance, especially a liquid that you drink or swallow in order to cure an illness","cn":"药；（尤指）药水"}]},"media":{"uk":"media/uk/medicine__gb_1.mp3","us":"media/us/medicine__us_1.mp3"}},"merges":{"oxford":{"phon":"mɜːdʒ","pos":"verb","senses":[{"en":"to combine or make two or more things combine to form a single thing （","cn":"使）合并，结合，并入"},{"en":"if two things merge , or if one thing merges into another, the differences between them gradually disappear so that it is impossible to separate them","cn":"相融；融入；渐渐消失在某物中"}]},"media":{"uk":"media/uk/merge__gb_1.mp3","us":"media/us/merge__us_1.mp3"}},"mesmeric":{"media":{"uk":"media/uk/mesmeric__gb_1.mp3","us":"media/us/mesmeric__us_1.mp3"},"oxford":{"phon":"mezˈmerɪk","pos":"adjective","senses":[{"en":"having such a strong effect on people that they cannot give their attention to anything else","cn":"迷人的；不可抗拒的","ex":{"en":"She gave a mesmeric performance.","cn":"她奉献了一场令人着迷的表演。"}}]},"examples":[{"en":"the mesmeric hum of the bees","cn":"蜜蜂那吸引人注意力的嗡嗡声"},{"en":"a mesmeric performance","cn":"引人入胜的表演"}]},"mechanism":{"media":{"uk":"media/uk/mechanism__gb_1.mp3","us":"media/us/mechanism__us_1.mp3"},"oxford":{"phon":"ˈmekənɪzəm","pos":"noun","senses":[{"en":"a set of moving parts in a machine that performs a task","cn":"机械装置；机件","ex":{"en":"a delicate watch mechanism","cn":"精致的手表机件"}},{"en":"a method or a system for achieving something","cn":"方法；机制","ex":{"en":"mechanisms for dealing with complaints from the general public","cn":"处理公众投诉的机制"}},{"en":"a system of parts in a living thing that together perform a particular function","cn":"（生物体内的）机制，构造","ex":{"en":"the balance mechanism in the ears","cn":"耳内的平衡机制"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"机械装置;机件","en":"In a machine or piece of equipment, a mechanism is a part, often consisting of a set of smaller parts, which performs a particular function.","ex":{"en":"...the locking mechanism","cn":"锁定装置"}},{"pos":"N-COUNT 可数名词","cn":"方法;途径;程序;机制","en":"A mechanism is a special way of getting something done within a particular system.","ex":{"en":"There's no mechanism for punishing arms exporters who break the rules.","cn":"对违规的武器出口商实施惩罚尚无执行机制。"}},{"pos":"N-COUNT 可数名词","cn":"(人为生存、对付困境的)机制，行为方式","en":"A mechanism is a part of your behaviour that is automatic and that helps you to survive or to cope with a difficult situation.","ex":{"en":"...a survival mechanism, a means of coping with intolerable stress.","cn":"一种生存机制，一种应对无法承受的压力的方法"}}]},"examples":[{"en":"Pain acts as a natural defence mechanism.","cn":"疼痛起着自然防护机制的作用。"},{"en":"mechanisms for dealing with complaints from the general public","cn":"处理公众投诉的机制"}]},"mediocre":{"media":{"uk":"media/uk/mediocre__gb_1.mp3","us":"media/us/mediocre__us_1.mp3"},"oxford":{"phon":"ˌmiːdiˈəʊkə(r)","pos":"adjective","senses":[{"en":"not very good; of only average standard","cn":"平庸的；普通的；平常的","ex":{"en":"a mediocre musician/talent/performance","cn":"平庸的音乐家／才能／表演"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（事物）普通的，平庸的，一般的","en":"If you describe something as mediocre, you mean that it is of average quality but you think it should be better.","ex":{"en":"His school record was mediocre.","cn":"他在学校成绩平平。"}}]},"examples":[{"en":"I thought the play was only mediocre.","cn":"我认为这部戏剧只是平庸之作。"},{"en":"a mediocre musician/talent/performance","cn":"平庸的音乐家/才能/表演"}]},"meaning":{"media":{"uk":"media/uk/meaning__gb_1.mp3","us":"media/us/meaning__us_1.mp3"},"oxford":{"phon":"ˈmiːnɪŋ","pos":"noun","senses":[{"en":"the thing or idea that a sound, word, sign, etc. represents","cn":"（声音、文字、信号等传递的）意义，意思","g":"[uncountable, countable]","sc":"of sound/word/sign","ex":{"en":"What's the meaning of this word?","cn":"这个单词的意思是什么？"}},{"en":"the things or ideas that somebody wishes to communicate to you by what they say or do","cn":"（想要表达的）意义，意思","g":"[uncountable, countable]","sc":"of what somebody says/does","ex":{"en":"It is important to make your meaning clear.","cn":"清楚表达意思很重要。"}},{"en":"the real importance of a feeling or an experience","cn":"真正重要性；价值","g":"[uncountable]","sc":"of feeling/experience","ex":{"en":"With Anna he learned the meaning of love.","cn":"通过与安娜相处，他明白了爱意味着什么。"}},{"en":"the ideas that a writer, artist, etc. wishes to communicate through a book, painting, etc.","cn":"（作家、艺术家等要表达的）意义，含意，思想","g":"[uncountable, countable]","sc":"of book/painting","ex":{"en":"several layers of meaning","cn":"若干层意义"}},{"en":"the quality or sense of purpose that makes you feel that your life is valuable","cn":"（人生的）意义，价值，目标","g":"[uncountable]","sc":"sense of purpose","ex":{"en":"Her life seemed to have lost all meaning.","cn":"她的生活似乎已毫无价值。"}},{"en":"intended to communicate or express something to somebody, without any words being spoken","cn":"意味深长的；意在言外的","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"意思;意义;含义","en":"The meaning of a word, expression, or gesture is the thing or idea that it refers to or represents and which can be explained using other words.","ex":{"en":"I hadn't a clue to the meaning of 'activism'","cn":"我根本不明白 activism 的意思。"}},{"pos":"N-VAR 可变名词","cn":"(言语、书、电影等的)含义，主旨，意图","en":"The meaning of what someone says or of something such as a book or film is the thoughts or ideas that are intended to be expressed by it.","ex":{"en":"Unsure of the meaning of this remark, Ryle chose to remain silent","cn":"由于不确定这句话究竟是什么意思，赖尔选择了保持沉默。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(活动、行为等的)意义，价值","en":"If an activity or action has meaning, it has a purpose and is worthwhile.","ex":{"en":"Art has real meaning when it helps people to understand themselves.","cn":"当艺术有助于人们了解自身的时候才有真正的意义。"}},{"pos":"PHRASE 短语","cn":"(由于缺乏经历、资质等)不理解这个词的含义，不知道什么叫…","en":"If you mention something and say that someone doesn't know the meaning of the word, you are emphasizing that they have never experienced the thing mentioned or do not have the quality mentioned.","ex":{"en":"Don't mention failure when Kevin is around. He doesn't know the meaning of the word.","cn":"凯文在的时候不要提“失败”这个词。他不知道什么叫“失败”。"}}]},"examples":[{"en":"What's the meaning of this? I explicitly told you not to leave the room.","cn":"这是什么意思？我明确地告诉过你不要离开这个房间。"},{"en":"With Anna he learned the meaning of love.","cn":"通过与安娜相处，他明白了爱意味着什么。"}]},"medicine":{"media":{"uk":"media/uk/medicine__gb_1.mp3","us":"media/us/medicine__us_1.mp3"},"oxford":{"phon":"ˈmedsn","pos":"noun","senses":[{"en":"the study and treatment of diseases and injuries","cn":"医学；医疗","g":"[uncountable]","ex":{"en":"advances in modern medicine","cn":"现代医学的发展"}},{"en":"a substance that you take in order to cure an illness, especially a liquid that you drink or swallow","cn":"药；药物；（尤指）药水","g":"[uncountable, countable]","lab":"British English","ex":{"en":"Did you take your medicine?","cn":"你吃过药了吗？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"医学;疗法;医疗","en":"Medicine is the treatment of illness and injuries by doctors and nurses.","ex":{"en":"He pursued a career in medicine","cn":"他从事医学。"}},{"pos":"N-MASS 物质名词","cn":"（吞服的）药，药物，药剂","en":"Medicine is a substance that you drink or swallow in order to cure an illness.","ex":{"en":"People in hospitals are dying because of shortage of medicine.","cn":"由于药品匮乏，医院里的病人濒临死亡。"}}]},"examples":[{"en":"Let the bully have a taste of his own medicine.","cn":"让那个恶棍得到报应吧。"},{"en":"Laughter is the best medicine.","cn":"欢笑是一副良药。"}]},"meets":{"oxford":{"phon":"miːt","pos":"verb","senses":[{"en":"to be in the same place as sb by chance and talk to them","cn":"相遇；相逢；遇见"},{"en":"to come together formally in order to discuss sth","cn":"开会；会晤"}]},"media":{"uk":"media/uk/meet__gb_1.mp3","us":"media/us/meet__us_1.mp3"}},"me":{"media":{"uk":"media/uk/me__gb_1.mp3","us":"media/us/me__us_1.mp3"},"oxford":{"phon":"mi","pos":"pronoun","senses":[{"en":"the form of I that is used when the speaker or writer is the object of a verb or preposition, or after the verb be","cn":"（I 的宾格）我","lab":"British English","ex":{"en":"Don't hit me.","cn":"别打我。"}},{"en":"the third note of a major scale","cn":"大调音阶的第 3 音","pos":"noun"},{"en":"an illness that makes people feel extremely weak and tired and that can last a long time (the abbreviation for ‘myalgic encephalomyelitis’)","cn":"肌痛性脑脊髓炎，慢性疲劳综合征（全写为 myalgic encephalomyelitis）","g":"[uncountable]","lab":"British English","ex":{"en":"She’s had ME for six months.","cn":"她已经有了我六个月了。"},"pos":"noun"},{"en":"medical examiner","cn":"法医；验尸官","lab":"North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"肌痛性脑脊髓炎;慢性疲劳综合征","en":"ME is a long-lasting illness that is thought to be caused by a virus. Its symptoms include feeling tired all the time and muscle pain. ME is an abbreviation for (缩略 =) 'myalgic encephalomyelitis'."}]},"examples":[{"en":"You're taller than me.","cn":"你比我高。"},{"en":"Hello, it's me.","cn":"喂，是我。"}]},"method":{"media":{"uk":"media/uk/method__gb_1.mp3","us":"media/us/method__us_1.mp3"},"oxford":{"phon":"ˈmeθəd","pos":"noun","senses":[{"en":"a particular way of doing something","cn":"方法；办法；措施","g":"[countable]","ex":{"en":"Which method is the most effective?","cn":"哪种方法最有效？"}},{"en":"the quality of being well planned and organized","cn":"条理；有条不紊","g":"[uncountable]","ex":{"en":"There's very little method in his approach.","cn":"他的方法很少有方法。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方法;办法","en":"A method is a particular way of doing something.","ex":{"en":"The pill is the most efficient method of birth control.","cn":"服用避孕药是最有效的避孕方法。"}}]},"examples":[{"en":"a reliable/effective/scientific method of data analysis","cn":"可靠的/有效的/科学的数据分析方法"},{"en":"the best method for arriving at an accurate prediction of the costs","cn":"准确预测成本的最佳方法"}]},"meagre":{"media":{"uk":"media/uk/meagre__gb_1.mp3","us":"media/us/meagre__us_1.mp3"},"oxford":{"phon":"ˈmiːɡə(r)","pos":"adjective","senses":[{"en":"small in quantity and poor in quality","cn":"少量且劣质的","ex":{"en":"a meagre diet of bread and water","cn":"只有面包和水的简朴饮食"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"数量很少的;微薄的;不足的;贫乏的","en":"If you describe an amount or quantity of something as meagre, you are critical of it because it is very small or not enough.","ex":{"en":"The bank's staff were already angered by a meagre 3.1% pay rise","cn":"银行职员对只加薪3.1%已心生怒火。"}}]},"examples":[{"en":"She supplements her meagre income by cleaning at night.","cn":"她靠做夜间清洁工来补贴其微薄的收入。"},{"en":"a meagre diet of bread and water","cn":"只有面包和水的简朴饮食"}]},"merge":{"media":{"uk":"media/uk/merge__gb_1.mp3","us":"media/us/merge__us_1.mp3"},"oxford":{"phon":"mɜːdʒ","pos":"verb","senses":[{"en":"to combine or make two or more things combine to form a single thing","cn":"（使）合并，结合，并入","g":"[intransitive, transitive]","ex":{"en":"The banks are set to merge next year.","cn":"这几家银行准备明年合并。"}},{"en":"if two things merge, or if one thing merges into another, the differences between them gradually disappear so that it is impossible to separate them","cn":"相融；融入；渐渐消失在某物中","g":"[intransitive]","ex":{"en":"The hills merged into the dark sky behind them.","cn":"山峦渐渐隐入背后漆黑的夜空之中。"}}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"(使)合并;(使)融合","en":"If one thing merges with another, or is merged with another, they combine or come together to make one whole thing. You can also say that two things merge, or are merged .","ex":{"en":"My life merged with his","cn":"我和他的生活合而为一。"}},{"pos":"V-RECIP 相互动词","cn":"渐渐消失于;融入;相融","en":"If one sound, colour, or object merges into another, the first changes so gradually into the second that you do not notice the change.","ex":{"en":"Like a chameleon, he could merge unobtrusively into the background","cn":"他就像一条变色龙，可以神不知鬼不觉地隐藏在背景中间。"}}]},"examples":[{"en":"Fact and fiction merge together in his latest thriller.","cn":"在他最新的惊险小说中，真实和虚构交织在一起。"},{"en":"The villages expanded and merged into one large town.","cn":"这些村庄扩大了并且结合成了一个大集镇。"}]},"menu":{"media":{"uk":"media/uk/menu__gb_1.mp3","us":"media/us/menu__us_1.mp3"},"oxford":{"phon":"ˈmenjuː","pos":"noun","senses":[{"en":"a list of the food that is available at a restaurant or to be served at a meal","cn":"菜单","lab":"especially British English","ex":{"en":"May we have the menu?","cn":"把菜单给我们好吗？"}},{"en":"a list of possible choices that are shown on a computer screen","cn":"（功能选择）菜单；选单","lab":"computing","ex":{"en":"a pull-down/pop-up menu","cn":"下拉式／弹出式菜单"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"菜单","en":"In a restaurant or café or at a formal meal, the menu is a list of the food and drinks that are available.","ex":{"en":"A waiter offered him the menu","cn":"一个服务生给他送上了菜单。"}},{"pos":"N-COUNT 可数名词","cn":"饭菜;菜肴","en":"A menu is the food that you serve at a meal.","ex":{"en":"Try out the menu on a few friends","cn":"让几个朋友尝尝这道菜。"}},{"pos":"N-COUNT 可数名词","cn":"(电脑屏幕上的)菜单，功能选择单，选项单","en":"On a computer screen, a menu is a list of choices. Each choice represents something that you can do using the computer."}]},"examples":[{"en":"What's on the menu (= for dinner) tonight?","cn":"今晚有什么菜？"},{"en":"to ask for/look at the menu","cn":"要/看菜单"}]},"mens":{"media":{"uk":"media/uk/men__gb_1.mp3","us":"media/us/men__us_1.mp3"}},"megawatt":{"media":{"uk":"media/uk/megawatt__gb_1.mp3","us":"media/us/megawatt__us_1.mp3"},"oxford":{"phon":"ˈmeɡəwɒt","pos":"noun","senses":[{"en":"a unit for measuring electrical power; one million watts","cn":"兆瓦，百万瓦特（电能计量单位）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兆瓦;百万瓦特","en":"A megawatt is a unit of power. One megawatt is a million watts.","ex":{"en":"The project is designed to generate around 30 megawatts of power for the national grid.","cn":"该工程计划为国家电网发电约30兆瓦。"}}]}},"melted":{"oxford":{"phon":"melt","pos":"verb","senses":[{"en":"to become or make sth become liquid as a result of heating （","cn":"使）熔化，融化"},{"en":"to become or to make a feeling, an emotion, etc. become gentler and less strong （","cn":"使）软化，变得温柔"}]},"media":{"uk":"media/uk/melt__gb_1.mp3","us":"media/us/melt__us_1.mp3"}},"mercy":{"media":{"uk":"media/uk/mercy__gb_1.mp3","us":"media/us/mercy__us_1.mp3"},"oxford":{"phon":"ˈmɜːsi","pos":"noun","senses":[{"en":"a kind or forgiving attitude towards somebody that you have the power to harm or right to punish","cn":"仁慈；宽恕","g":"[uncountable]","ex":{"en":"to ask/beg/plead for mercy","cn":"请求／乞求／祈求宽恕"}},{"en":"an event or a situation to be grateful for, usually because it stops something unpleasant","cn":"幸运；恩惠","g":"[countable, usually singular]","lab":"informal","ex":{"en":"It's a mercy she wasn't seriously hurt.","cn":"幸运的是她伤势不重。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仁慈;怜悯;宽恕","en":"If someone in authority shows mercy, they choose not to harm someone they have power over, or they forgive someone they have the right to punish.","ex":{"en":"Neither side took prisoners or showed any mercy","cn":"双方都没有抓俘虏，也没有表现出丝毫的心慈手软。"}},{"pos":"ADJ 形容词","cn":"慈善的;救援的","en":"Mercy is used to describe a special journey to help someone in great need, such as people who are sick or made homeless by war.","ex":{"en":"She vanished nine months ago while on a mercy mission to West Africa","cn":"9个月前她在去西非的慈善之旅中消失了。"}},{"pos":"N-COUNT 可数名词","cn":"幸运;侥幸","en":"If you refer to an event or situation as a mercy, you mean that it makes you feel happy or relieved, usually because it stops something unpleasant happening.","ex":{"en":"It really was a mercy that he'd died so rapidly at the end","cn":"他最后去得那么快，真是谢天谢地。"}},{"pos":"PHRASE 短语","cn":"完全由…支配;任由…摆布","en":"If one person or thing is at the mercy of another, the first person or thing is in a situation where they cannot prevent themselves being harmed or affected by the second.","ex":{"en":"Buildings are left to decay at the mercy of vandals and the weather","cn":"建筑物因人为的肆意破坏及日晒雨淋而日益破败。"}},{"pos":"PHRASE 短语","cn":"为坏情况没有变得更糟而庆幸","en":"If you tell someone who is in an unpleasant situation that they should be grateful or thankful for small mercies, you mean that although their situation is bad, it could be even worse, and so they should be happy.","ex":{"en":"But so low has morale sunk that the team and the fans would have been grateful for small mercies.","cn":"士气如此低沉，一丁点的好运都会让队员和球迷庆幸不已。"}},{"pos":"PHRASE 短语","cn":"听凭…发落","en":"If you throw yourself on someone's mercy, you put yourself in a situation where they will have complete power to decide how to treat you, for example whether to punish or forgive you.","ex":{"en":"He's going to throw himself on the mercy of the court.","cn":"他准备听凭法庭发落。"}}]},"examples":[{"en":"They showed no mercy to their hostages.","cn":"他们对人质丝毫不讲仁慈。"},{"en":"The troops are on a mercy mission (= a journey to help people) in the war zone.","cn":"部队出发救助战地民众。"}]},"member":{"media":{"uk":"media/uk/member__gb_1.mp3","us":"media/us/member__us_1.mp3"},"oxford":{"phon":"ˈmembə(r)","pos":"noun","senses":[{"en":"a person, an animal or a plant that belongs to a particular group","cn":"成员；分子","ex":{"en":"a member of the family/community","cn":"家庭／社区的成员"}},{"en":"a person, a country or an organization that has joined a particular group, club or team","cn":"成员；会员","ex":{"en":"party/union members","cn":"党员；工会会员"}},{"en":"(in the UK) a Member of Parliament","cn":"（英国）下院议员","ex":{"en":"the Hon. Member for Brent North","cn":"布伦特北区议员阁下"}},{"en":"a person who has been given an honour","cn":"勋章获得者","ex":{"en":"Murray was made a Member of the Order of Australia for his services to Association Football.","cn":"穆雷因对足球运动的贡献而获得澳大利亚勋章。"}},{"en":"a part of the body, especially an arm or a leg","cn":"身体部位（尤指胳膊或腿）","lab":"old use or literary"},{"en":"a penis. People say ‘member’ to avoid saying ‘penis’.","cn":"（委婉说法，与 penis 同义，即阴茎）","lab":"formal"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（团体的）成员，一分子","en":"A member of a group is one of the people, animals, or things belonging to that group.","ex":{"en":"He refused to name the members of staff involved","cn":"他拒绝说出所涉及员工的姓名。"}},{"pos":"N-COUNT 可数名词","cn":"会员;成员","en":"A member of an organization such as a club or a political party is a person who has officially joined the organization.","ex":{"en":"The support of our members is of great importance to the Association","cn":"会员的支持对于我们协会来说非常重要。"}},{"pos":"ADJ 形容词","cn":"(某国际组织的)会员国，成员国","en":"A member country or member state is one of the countries that has joined an international organization or group.","ex":{"en":"...the member countries of the European Free Trade Association.","cn":"欧洲自由贸易联盟的成员国"}},{"pos":"N-COUNT 可数名词","cn":"议员","en":"A member or Member is a person who has been elected to a parliament or legislature.","ex":{"en":"He was elected to Parliament as the Member for Leeds.","cn":"他当选为利兹市议员而进入了议会。"}}]},"examples":[{"en":"characteristics common to all members of the species","cn":"这一物种中所有个体的共同特点"},{"en":"How much does it cost to become a member?","cn":"要成为会员得花多少钱？"}]},"meant":{"media":{"uk":"media/uk/meant__gb_1.mp3","us":"media/us/meant__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"Meant is the past tense and past participle of mean ."},{"pos":"ADJ 形容词","cn":"原本打算的;理应的","en":"You use meant to to say that something or someone was intended to be or do a particular thing, especially when they have failed to be or do it.","ex":{"en":"I can't say any more, it's meant to be a big secret","cn":"我再也无可奉告了，这本是重大的秘密。"}},{"pos":"ADJ 形容词","cn":"为…而做的;为…而准备的","en":"If something is meant for particular people or for a particular situation, it is intended for those people or for that situation.","ex":{"en":"Fairy tales weren't just meant for children","cn":"童话故事不仅仅是写给孩子们的。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"理应发生;应该","en":"If you say that something is meant to happen, you mean that it is expected to happen or that it ought to happen.","ex":{"en":"The peculiar thing about getting engaged is that you're meant to announce it to everyone","cn":"订婚的特别之处在于，你就应该让人人知道你订婚了。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"公认(具有某种特性或特点);具有…的名声","en":"If you say that something is meant to have a particular quality or characteristic, you mean that it has a reputation for being like that.","ex":{"en":"Beaujolais is meant to be a really good wine.","cn":"博若莱葡萄酒是公认的佳酿。"}}]}},"mesquite":{"media":{"uk":"media/uk/mesquite__gb_1.mp3","us":"media/us/mesquite__us_1.mp3"},"oxford":{"phon":"meˈskiːt","pos":"noun","senses":[{"en":"a North American tree that grows in the south-western US and Mexico, often used for making charcoal for grilling food","cn":"牧豆树（产于北美，常用以制烧烤用的木炭）","ex":{"en":"mesquite-grilled chicken","cn":"牧豆树炭烤鸡"}}]},"examples":[{"en":"mesquite-grilled chicken","cn":"牧豆树炭烤鸡"}]},"metaphors":{"oxford":{"phon":"ˈmetəfə(r)","pos":"noun","senses":[{"en":"a word or phrase used to describe sb/sth else, in a way that is different from its normal use, in order to show that the two things have the same qualities and to make the description more powerful, for example She has a heart of ","cn":"暗喻；隐喻"}]},"media":{"uk":"media/uk/metaphor__gb_1.mp3","us":"media/us/metaphor__us_1.mp3"}},"mezzanine":{"media":{"uk":"media/uk/mezzanine__gb_1.mp3","us":"media/us/mezzanine__us_1.mp3"},"oxford":{"phon":"ˈmezəniːn","pos":"noun","senses":[{"en":"a floor that is built between two floors of a building and is smaller than the other floors","cn":"（介于两层楼之间、比其他楼层小的）夹层","ex":{"en":"a bedroom on the mezzanine","cn":"夹层楼面上的卧室"}},{"en":"the first area of seats above the ground floor in a theatre; the first few rows of these seats","cn":"（戏院的）最低层楼厅（前座）","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(两层楼之间的)夹层楼面,夹楼","en":"A mezzanine is a small floor which is built between two main floors of a building.","ex":{"en":"...the dining room on the mezzanine.","cn":"位于夹层的餐厅"}},{"pos":"N-COUNT 可数名词","cn":"(剧院的)最底层楼厅;最底层楼厅的前座","en":"The mezzanine is the lowest balcony in a theatre, or the front rows in the lowest balcony."}]},"examples":[{"en":"a bedroom on the mezzanine","cn":"夹层楼面上的卧室"},{"en":"a mezzanine floor","cn":"夹楼层"}]},"measured":{"media":{"uk":"media/uk/measured__gb_1.mp3","us":"media/us/measured__us_1.mp3"},"oxford":{"phon":"ˈmeʒəd","pos":"adjective","senses":[{"en":"slow and careful; showing control","cn":"缓慢谨慎的；慎重的；克制的","ex":{"en":"She replied in a measured tone to his threat.","cn":"她以很有分寸的语气回应了他的威胁。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"仔细的;谨慎小心的","en":"You use measured to describe something that is careful and deliberate.","ex":{"en":"The men spoke in soft, measured tones","cn":"这些人说话的语气轻柔而平稳。"}}]},"examples":[{"en":"He walked down the corridor with measured steps.","cn":"他迈着缓慢而匀称的脚步沿着走廊走去。"},{"en":"She replied in a measured tone to his threat.","cn":"她以很有分寸的语气回应了他的威胁。"}]},"mentally":{"media":{"uk":"media/uk/mentally__gb_1.mp3","us":"media/us/mentally__us_1.mp3"},"oxford":{"phon":"ˈmentəli","pos":"adverb","senses":[{"en":"connected with or happening in the mind","cn":"精神上；智力上；思想上","ex":{"en":"mentally ill","cn":"有精神病"}}]},"examples":[{"en":"The question is, was the man insane when he committed the crime?","cn":"问题在于这男人犯罪时是否处于精神失常状态？"},{"en":"Mentally, I began making a list of things I had to do.","cn":"我开始在脑子里盘算我该做哪些事情。"}]},"messages":{"oxford":{"phon":"ˈmesɪdʒ","pos":"noun","senses":[{"en":"a written or spoken piece of information, etc. that you send to sb or leave for sb when you cannot speak to them yourself （","cn":"书面或口头的）信息，消息，音信"},{"en":"a piece of information sent in electronic form, for example by email or mobile/cell phone","cn":"电邮信息；（手机）短信息"}]}},"meats":{"oxford":{"phon":"miːt","pos":"noun","senses":[{"en":"the flesh of an animal or a bird eaten as food; a particular type of this","cn":"肉类；（某种）食用肉"},{"en":"the important or interesting part of sth","cn":"重要的部分；有趣的部分"}]}},"mentions":{"oxford":{"phon":"ˈmenʃn","pos":"verb","senses":[{"en":"to write or speak about sth/sb, especially without giving much information","cn":"提到；写到；说到"},{"en":"( informal ) used as a polite answer when sb has thanked you for sth （","cn":"别人道谢时回答）不客气"}]}},"meanings":{"oxford":{"phon":"ˈmiːnɪŋ","pos":"noun","senses":[{"en":"the thing or idea that a sound, word, sign, etc. represents （","cn":"声音、文字、信号等传递的）意义，意思"},{"en":"the things or ideas that sb wishes to communicate to you by what they say or do （","cn":"想要表达的）意义，意思"}]}},"meadows":{"oxford":{"phon":"ˈmedəʊ","pos":"noun","senses":[{"en":"a field covered in grass, used especially for hay","cn":"草地；牧场"}]}},"measuring":{"oxford":{"phon":"ˈmeʒə(r)","pos":"verb","senses":[{"en":"to find the size, quantity, etc. of sth in standard units","cn":"测量；度量"},{"en":"to be a particular size, length, amount, etc. （","cn":"指尺寸、长短、数量等）量度为"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指烹饪时)测量（或称量）用的(壶、杯、匙等)","en":"A measuring jug, cup, or spoon is specially designed for measuring quantities, especially in cooking."}]}},"measurements":{"oxford":{"phon":"ˈmeʒəmənt","pos":"noun","senses":[{"en":"the act or the process of finding the size, quantity or degree of sth","cn":"测量；度量"},{"en":"the size, length or amount of sth （","cn":"某物的）尺寸，长度，数量"}]}},"megawatts":{"oxford":{"phon":"ˈmeɡəwɒt","pos":"noun","senses":[{"en":"a unit for measuring electrical power; one million watts","cn":"兆瓦，百万瓦特（电能计量单位）"}]}},"mentioning":{"oxford":{"phon":"ˈmenʃn","pos":"verb","senses":[{"en":"to write or speak about sth/sb, especially without giving much information","cn":"提到；写到；说到"},{"en":"( informal ) used as a polite answer when sb has thanked you for sth （","cn":"别人道谢时回答）不客气"}]}},"meals":{"oxford":{"phon":"miːl","pos":"noun","senses":[{"en":"an occasion when people sit down to eat food, especially breakfast, lunch or dinner","cn":"早（或午、晚）餐；一顿饭"},{"en":"the food that is eaten at a meal","cn":"一餐所吃的食物"}]}},"measures":{"oxford":{"phon":"ˈmeʒə(r)","pos":"verb","senses":[{"en":"to find the size, quantity, etc. of sth in standard units","cn":"测量；度量"},{"en":"to be a particular size, length, amount, etc. （","cn":"指尺寸、长短、数量等）量度为"}]}},"members":{"oxford":{"phon":"ˈmembə(r)","pos":"noun","senses":[{"en":"a person, an animal or a plant that belongs to a particular group","cn":"成员；分子"},{"en":"a person, a country or an organization that has joined a particular group, club or team","cn":"成员；会员"}]}},"methods":{"oxford":{"phon":"ˈmeθəd","pos":"noun","senses":[{"en":"a particular way of doing sth","cn":"方法；办法；措施"},{"en":"the quality of being well planned and organized","cn":"条理；有条不紊"}]}},"meetings":{"oxford":{"phon":"ˈmiːtɪŋ","pos":"noun","senses":[{"en":"an occasion when people come together to discuss or decide sth","cn":"会议；集会"},{"en":"the people at a meeting （","cn":"统称）与会者"}]}},"mentioned":{"oxford":{"phon":"ˈmenʃn","pos":"verb","senses":[{"en":"to write or speak about sth/sb, especially without giving much information","cn":"提到；写到；说到"},{"en":"( informal ) used as a polite answer when sb has thanked you for sth （","cn":"别人道谢时回答）不客气"}]}},"memories":{"oxford":{"phon":"ˈmeməri","pos":"noun","senses":[{"en":"your ability to remember things","cn":"记忆力；记性"},{"en":"the period of time that sb is able to remember events","cn":"记忆所及的时期；回忆所及的范围"}]}},"melons":{"oxford":{"phon":"ˈmelən","pos":"noun","senses":[{"en":"a large fruit with hard green, yellow or orange skin, sweet flesh and juice and a lot of seeds","cn":"甜瓜；瓜"}]}},"mellow":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色)柔和的,温暖的","en":"Mellow is used to describe things that have a pleasant, soft, rich colour, usually red, orange, yellow, or brown.","ex":{"en":"...a classic Queen Anne house of mellow red brick with a white portico.","cn":"一座典型的安妮女王时代的房屋，有着色彩柔和的红砖和白色的门廊"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)悦耳的，圆润的;(味道)香醇的","en":"A mellow sound or flavour is pleasant, smooth, and rich.","ex":{"en":"His voice was deep and mellow and his speech had a soothing and comforting quality.","cn":"他的嗓音低沉悦耳，他的讲话能抚慰人心。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变平和;(使)变得成熟","en":"If someone mellows or if something mellows them, they become kinder or less extreme in their behaviour, especially as a result of growing older.","ex":{"en":"When the children married and had children of their own, he mellowed a little","cn":"等孩子们结了婚又有了自己的小孩以后，他变得平和了一些。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指喝过酒或品尝过美食后)怡然自得的","en":"If someone is mellow, they feel very relaxed and cheerful, especially as the result of alcohol or good food.","ex":{"en":"He'd had a few glasses of champagne himself and was fairly mellow","cn":"他自己也已几杯香槟下肚，很是飘飘然。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not getting angry, nervous, or upset, even in a difficult situation","cn":""},{"en":"not worried about anything, especially so that people feel comfortable","cn":""},{"en":"very relaxed and not worried – used especially by young people","cn":""}]},"vocab":{"pos":"adj v adv","senses":[{"en":"When something becomes mellow , it gets softer or more relaxed. People are often said to mellow with age, meaning their aggressiveness, their sarcasm, and their short temper have given way to a more easygoing, genial manner."}]},"collocations":{"phrases":["VERBS be, feel, look, seem | become, grow","ADV. extremely, very | beautifully, delightfully, wonderfully a delightfully mellow flavour"]},"media":{"uk":"media/ldoce/hwd/bre/f/mellow_v0205.mp3","us":"media/ldoce/hwd/ame/4/mellow1.mp3"},"examples":[{"en":"A period spent working abroad had done nothing to mellow him.","cn":"他在海外工作了一段时间，却没有变得老练。"},{"en":"Mellow music and lighting helped to create the right atmosphere.","cn":"柔和的音乐和灯光衬托出了适宜的氛围。"}],"oxford":{"phon":"ˈmeləʊ","pos":"adjective","senses":[{"en":"soft, rich and pleasant","cn":"柔和丰富的","ex":{"en":"mellow autumn colours","cn":"宜人的秋色"}},{"en":"smooth and pleasant","cn":"醇香的；甘美的","ex":{"en":"a mellow, fruity wine","cn":"醇正浓香的葡萄酒"}},{"en":"calm, gentle and reasonable because of age or experience","cn":"老练的；成熟的","ex":{"en":"Dad's certainly grown mellower with age.","cn":"随着年龄的增长，父亲当然是更老练了。"}},{"en":"relaxed, calm and happy, especially after drinking alcohol","cn":"（尤指酒后）飘飘然的，怡然自得的","lab":"informal","ex":{"en":"After two glasses of wine, I was feeling mellow.","cn":"两杯葡萄酒下肚，我就飘飘然了。"}},{"en":"to become or make somebody become less extreme in behaviour, etc., especially as a result of growing older","cn":"（使）成熟，老成","g":"[intransitive, transitive]","ex":{"en":"She had mellowed a great deal since their days at college.","cn":"大学毕业以后，她成熟了许多。"},"pos":"verb"},{"en":"to become or to make a colour become less bright, especially over a period of time","cn":"（尤指一段时间后颜色）变柔和；（使颜色）柔和","g":"[intransitive, transitive]","pos":"verb"},{"en":"to develop or make wine develop a pleasant and less bitter taste over a period of time","cn":"（使酒）更加醇香","g":"[intransitive, transitive]","pos":"verb"}]}},"melody":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旋律;曲调","en":"A melody is a tune."},{"pos":"N-UNCOUNT 不可数名词","cn":"婉转;悦耳","en":"Melody is the quality of having a pleasant tune.","ex":{"en":"Her voice was full of melody.","cn":"她的声音非常悦耳。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sounds made by musical instruments or people singing","cn":""},{"en":"the main series of musical notes in a piece of music","cn":""},{"en":"the main series of notes in a piece of music that has many notes being played at the same time, especially in classical music","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"In any musical composition, there is a dominant line that creates a tone pattern known as the piece's melody . There are specific rules for the musical composition of a melody , and most fall into regular patterns."}]},"collocations":{"phrases":["ADJ. beautiful, lovely, sweet | bold, simple, strong | complex | haunting, memorable | familiar, popular, traditional","VERB + MELODY play, sing | hear | have Most of her songs have a bold melody. | write"]},"media":{"uk":"media/ldoce/hwd/bre/c/melody0205.mp3","us":"media/ldoce/hwd/ame/0/melody.mp3"},"examples":[{"en":"A few bars of melody drifted towards us.","cn":"几小节乐曲从远处传来。"},{"en":"The melody is then taken up by the flutes.","cn":"接着由长笛奏主旋律。"}],"oxford":{"phon":"ˈmelədi","pos":"noun","senses":[{"en":"a tune, especially the main tune in a piece of music written for several instruments or voices","cn":"旋律；曲调；（尤指）主旋律","g":"[countable]","lab":"British English","ex":{"en":"a haunting melody","cn":"萦绕心头的旋律"}},{"en":"a piece of music or a song with a clear or simple tune","cn":"（旋律简洁的）乐曲，歌曲","g":"[countable]","ex":{"en":"old Irish melodies","cn":"古老的爱尔兰歌曲"}},{"en":"the arrangement of musical notes in a tune","cn":"乐曲的音符编排","g":"[uncountable]","ex":{"en":"a few bars of melody drifted towards us","cn":"几小节乐曲从远处传来。"}}]}},"memento":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纪念物;纪念品","en":"A memento is an object which you keep because it reminds you of a person or a special occasion.","ex":{"en":"More anglers are taking cameras when they go fishing to provide a memento of catches.","cn":"更多的垂钓者去钓鱼的时候带上了照相机，以便钓上鱼后留个纪念。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small thing that you keep to remind you of someone or something","cn":"小纪念物﹐小纪念品"}]},"vocab":{"pos":"n","senses":[{"en":"A memento is a keepsake of something you want to remember. You may keep photographs as a memento of a great family reunion — except for that one photo where Aunt Bonnie is wearing the lampshade and singing \"Respect.\" No one wants to remember that!"}]},"collocations":{"phrases":["ADJ. family, personal | permanent","VERB + MEMENTO be presented with, receive","PREP. as a ~ They gave him a watch as a memento of his time with the company. | ~ for The director will be presented with a memento for his "]},"media":{"uk":"media/ldoce/hwd/bre/6/memento0205.mp3","us":"media/ldoce/hwd/ame/8/memento.mp3"},"examples":[{"en":"a memento of our trip to Italy","cn":"我们意大利之旅的纪念品"},{"en":"I kept the bottle as a memento of my time in Spain.","cn":"我留着这个瓶子是为了纪念我在西班牙度过的时光。"}],"oxford":{"phon":"məˈmentəʊ","pos":"noun","senses":[{"en":"a thing that you keep or give to somebody to remind you or them of a person or place","cn":"纪念品","ex":{"en":"a memento of our trip to Italy","cn":"我们意大利之旅的纪念品"}}]}},"measles":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麻疹","en":"Measles is an infectious illness that gives you a high temperature and red spots on your skin."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an infectious illness in which you have a fever and small red spots on your face and body. People often have measles when they are children.","cn":"麻疹"}]},"collocations":{"phrases":["VERB + MEASLES have All our children have had the measles. | catch, contract | immunize sb against, vaccinate sb against","MEASLES + NOUN virus | vaccination, vaccine •"]},"media":{"uk":"media/ldoce/hwd/bre/a/measles0205.mp3","us":"media/ldoce/hwd/ame/e/measles.mp3"},"oxford":{"phon":"ˈmiːzlz","pos":"noun","senses":[{"en":"a disease, especially of children, that causes a high temperature and small red spots that cover the whole body","cn":"麻疹","ex":{"en":"All our children have had the measles.","cn":"我们所有的孩子都出过麻疹。"}}]}},"mexico":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country to the south of the US and to the north of Guatemala. Population: 116,220,947 (2014). Capital: Mexico City. The official language is Spanish, and most people belong to the Roman Catholic religion. It has had a strong influence on US culture , especia","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/lpd_mexico.mp3","us":"media/ldoce/hwd/ame/8/p028-000008210.mp3"},"oxford":{"phon":"ˈmeksɪkəʊ","pos":"noun","senses":[{"en":"a country in southern North America","cn":"墨西哥（北美洲南部国家）"}]}},"mesopotamia":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an area in western Asia around the River Tigris and the River Euphrates in Iraq, where, in ancient times, the world's first cities were built and several important ancient civilization s developed","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000008191.mp3","us":"media/ldoce/hwd/ame/8/p028-000008191.mp3"}},"medication":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"药物;药","en":"Medication is medicine that is used to treat and cure illness.","ex":{"en":"She stopped taking the prescribed medications","cn":"她不再服用医生开的药。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used for treating illness","cn":""},{"en":"a small piece of medicine that you swallow","cn":""},{"en":"a small piece of solid medicine","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your doctor prescribes something for you to take, it's medication . Medication is another way to say \"medicine\" or \"drug.\" Your poison ivy rash might be so bad that you need to take medication to stop the itching."}]},"collocations":{"phrases":["ADJ. prescribed | over-the-counter | regular","VERB + MEDICATION be on, receive, take | prescribe (sb) | administer, give sb | stop She stopped the medication because of side effects. | n","PREP. ~ for He is on regular medication for his fits."]},"media":{"uk":"media/ldoce/hwd/bre/0/medication0205.mp3","us":"media/ldoce/hwd/ame/c/medication.mp3"},"examples":[{"en":"Many flu medications are available without a prescription.","cn":"许多流感药不用处方就可以买到。"},{"en":"Are you currently taking any medication?","cn":"你在服用什么药吗？"}],"oxford":{"phon":"ˌmedɪˈkeɪʃn","pos":"noun","senses":[{"en":"a drug or another form of medicine that you take to prevent or to treat an illness; treatment involving drugs","cn":"药物；药物治疗","lab":"British English","ex":{"en":"Are you currently taking any medication?","cn":"你目前在服用什么药吗？"}}]}},"membrane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（连接或覆盖身体某些部位的）膜,薄膜","en":"A membrane is a thin piece of skin which connects or covers parts of a person's or animal's body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very thin piece of skin that covers or connects parts of your body 〔","cn":"覆盖或连接身体某些部分的〕膜﹐薄膜"},{"en":"a very thin layer of material that covers something 〔","cn":"覆盖某物的〕膜状物"}]},"vocab":{"pos":"n","senses":[{"en":"A membrane is a thin layer of something. For an example of a membrane, you don’t have to look far: your skin is a kind of membrane."}]},"collocations":{"phrases":["ADJ. thin | permeable, semi-permeable | cell | cellular | mucous","MEMBRANE + VERB surround sth","MEMBRANE + NOUN wall","PREP. through a/the ~ The virus then passes through the cell membrane."]},"media":{"uk":"media/ldoce/hwd/bre/d/membrane0205.mp3","us":"media/ldoce/hwd/ame/0/membrane.mp3"},"examples":[{"en":"a waterproof membrane","cn":"防水薄膜"},{"en":"Loud noise can damage the delicate membrane in the ear.","cn":"很响的噪声会损伤脆弱的耳膜。"}],"oxford":{"phon":"ˈmembreɪn","pos":"noun","senses":[{"en":"a thin layer of skin or tissue that connects or covers parts inside the body","cn":"（身体内的）膜","ex":{"en":"The virus passes through the cell membrane.","cn":"病毒穿过细胞膜。"}},{"en":"a very thin layer found in the structure of cells in plants","cn":"（植物细胞的）膜"},{"en":"a thin layer of material used to prevent air, liquid, etc. from entering a particular part of something","cn":"（可起防水、防风等作用的）膜状物","ex":{"en":"a waterproof membrane","cn":"防水薄膜"}}]}},"mercenary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(外籍)雇佣兵","en":"A mercenary is a soldier who is paid to fight by a country or group that they do not belong to."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"唯利是图的;见钱眼开的","en":"If you describe someone as mercenary, you are criticizing them because you think that they are only interested in the money that they can get from a particular person or situation."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soldier who fights for any country or group that will pay him","cn":"雇佣兵"},{"en":"only interested in the money you may be able to get from a person, job etc","cn":"只对钱感兴趣的﹐唯利是图的"}]},"vocab":{"pos":"n adj","senses":[{"en":"You might not want to call a mercenary a \"hireling\" to his face, but a mercenary is, after all, a soldier who gets paid to fight where needed, sometimes taking a heroic stand and other times just wanting payment for fighting."}]},"collocations":{"phrases":["ADJ. foreign","QUANT. army, band a small army of mercenaries","VERB + MERCENARY employ, hire, recruit | pay","MERCENARY + NOUN army"]},"media":{"uk":"media/ldoce/hwd/bre/c/mercenary_n0205.mp3","us":"media/ldoce/hwd/ame/4/mercenary1.mp3"},"examples":[{"en":"She's interested in him for purely mercenary reasons.","cn":"她对他感兴趣完全是为了贪图金钱。"},{"en":"a mercenary society/attitude","cn":"唯利是图的社会/态度"}],"oxford":{"phon":"ˈmɜːsənəri","pos":"noun","senses":[{"en":"a soldier who will fight for any country or group that offers payment","cn":"雇佣兵","ex":{"en":"foreign mercenaries","cn":"外国雇佣兵"}},{"en":"only interested in making or getting money","cn":"只为金钱的","ex":{"en":"a mercenary society/attitude","cn":"唯利是图的社会／态度"},"pos":"adjective"}]}},"menace":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"威胁;危险人物;祸害","en":"If you say that someone or something is a menace to other people or things, you mean that person or thing is likely to cause serious harm.","ex":{"en":"In my view you are a menace to the public.","cn":"在我看来，你对公众是个祸害。"}},{"pos":"N-COUNT 可数名词","cn":"惹麻烦的人(或物);惹人讨厌的人(或物)","en":"You can refer to someone or something as a menace when you want to say that they cause you trouble or annoyance.","ex":{"en":"You're a menace to my privacy, Kenworthy","cn":"肯沃西，你这人真讨厌，居然侵犯我的隐私。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"威胁性;危险气氛","en":"Menace is a quality or atmosphere that gives you the feeling that you are in danger or that someone wants to harm you.","ex":{"en":"There is a pervading sense of menace.","cn":"有一种危机四伏的感觉。"}},{"pos":"VERB 动词","cn":"危及;威胁","en":"If you say that one thing menaces another, you mean that the first thing is likely to cause the second thing serious harm.","ex":{"en":"The European states retained a latent capability to menace Britain's own security.","cn":"欧洲国家仍具有威胁英国自身安全的潜在能力。"}},{"pos":"VERB 动词","cn":"威胁;恐吓","en":"If you are menaced by someone, they threaten to harm you.","ex":{"en":"She's being menaced by her sister's latest boyfriend.","cn":"她正受到姐姐最近一个男友的恐吓。"}},{"pos":"PHRASE 短语","cn":"以威胁（或恐吓）的手段（索要钱财）","en":"If someone commits the crime of demanding money with menaces, they threaten to cause harm unless they are given the money.","ex":{"en":"He denies demanding money with menaces.","cn":"他否认有过勒索钱财的行为。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be likely to harm other people or things","cn":""},{"en":"if a situation or the existence of something poses a threat , it is dangerous to people","cn":""},{"en":"if an activity or a problem threatens something such as a place, animal, or way of life, it could cause it to no longer exist","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If it's threatening you or otherwise posing some sort of danger, then it's a menace . Angry rabid dogs, smog clouds, and annoying little brothers are all probable menaces ."}]},"collocations":{"phrases":["ADJ. growing, increased, increasing the growing menace of drugs | serious","VERB + MENACE pose the menace posed by car fumes | combat, counter Shop owners are struggling to combat the menace of armed robbery.","PREP. ~ to He's a menace to society. 2 threatening quality","ADJ. hidden, quiet, silent &lsquo;Where do you think you're going?&rsquo; he said with quiet menace.","PREP. with ~ eyes glittering with menace","PHRASES an air of menace The scar down his face added to his air of menace."]},"media":{"uk":"media/ldoce/hwd/bre/7/menace_n0205.mp3","us":"media/ldoce/hwd/ame/d/menace1.mp3"},"examples":[{"en":"a sense/an air/a hint of menace in his voice","cn":"他的话音里的威胁语气/腔调/意味"},{"en":"a new initiative aimed at beating the menace of illegal drugs","cn":"旨在打击非法毒品威胁的新举措"}],"oxford":{"phon":"ˈmenəs","pos":"noun","senses":[{"en":"a person or thing that causes, or may cause, serious damage, harm or danger","cn":"威胁；危险的人（或物）","g":"[countable, usually singular]","ex":{"en":"a new initiative aimed at beating the menace of illegal drugs","cn":"旨在打击非法毒品威胁的新举措"}},{"en":"an atmosphere that makes you feel threatened or frightened","cn":"恐怖的氛围；危险气氛","g":"[uncountable]","ex":{"en":"a sense/an air/a hint of menace in his voice","cn":"他话音里的威胁语气／腔调／意味"}},{"en":"a person or thing that is annoying or causes trouble","cn":"烦人的人（或事物）；引起麻烦的人（或事物）","g":"[countable, usually singular]","lab":"informal","ex":{"en":"They have become a public menace.","cn":"他们已经对公众构成了威胁。"}},{"en":"threats that somebody will cause harm if they do not get what they are asking for","cn":"恐吓；威胁","g":"[plural]","lab":"British English, law，，","ex":{"en":"to demand money with menaces","cn":"勒索钱财"}},{"en":"to be a possible danger to something/somebody","cn":"对…构成危险；危及；威胁到","ex":{"en":"The forests are being menaced by major development projects.","cn":"大型开发项目正在危及森林。"},"pos":"verb"}]}},"memorandum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"备忘录","en":"A memorandum is a written report that is prepared for a person or committee in order to provide them with information about a particular matter.","ex":{"en":"...a memorandum from the Ministry of Defence on its role","cn":"国防部发出的关于其职责的备忘录"}},{"pos":"N-COUNT 可数名词","cn":"(外交)备忘录","en":"A memorandum is an informal communication between governments which often states a particular diplomatic purpose or point of view.","ex":{"en":"...a memorandum of understanding for co-operation between our two countries.","cn":"为我们两国之间的合作而达成的谅解备忘录"}},{"pos":"N-COUNT 可数名词","cn":"(公司或组织内部的)公务便条，备忘录","en":"A memorandum is a short official note that is sent by one person to another within the same company or organization."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a memo","cn":"公务便条﹐备忘录"},{"en":"a short legal document that contains the important details of an agreement","cn":"协议备忘录"}]},"vocab":{"pos":"n","senses":[{"en":"A memorandum is a written record, message, or reminder. If your boss sends out a memorandum that there'll be a special teamwork-building workshop on Friday morning, get ready to do trust falls."}]},"collocations":{"phrases":["ADJ. internal | confidential, private, secret | brief | detailed | explanatory, factual","QUANT. copy","VERB + MEMORANDUM draft, draw up, prepare, write | issue, send, submit | sign | date The memorandum was dated 23 August, 2001. | leak","MEMORANDUM + VERB set sth out","PREP. in a/the ~ Refer to the terms set out in the company's memorandum. | ~ from, ~ of your memorandum of 18 February, 2001 | ~ on, ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/6/memorandum0205.mp3","us":"media/ldoce/hwd/ame/1/memorandum.mp3"},"examples":[{"en":"a detailed memorandum to the commission on employment policy","cn":"呈交委员会的有关就业政策的详细报告"},{"en":"an internal memorandum","cn":"内部备忘录"}],"oxford":{"phon":"ˌmeməˈrændəm","pos":"noun","senses":[{"en":"a memo (= an official note from one person to another in the same organization)","cn":"备忘录","lab":"formal","ex":{"en":"an internal memorandum","cn":"内部备忘录"}},{"en":"a record of a legal agreement that has not yet been formally prepared and signed","cn":"协议备忘录","lab":"law","ex":{"en":"The two sides have signed a memorandum of understanding aimed at ending the conflict.","cn":"双方签署了旨在结束冲突的谅解备忘录。"}},{"en":"a proposal or report on a particular subject for a person, an organization, a committee, etc.","cn":"建议书；报告","ex":{"en":"a detailed memorandum to the commission on employment policy","cn":"呈交委员会的有关就业政策的详细报告"}}]}},"merchant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指外贸)商人，批发商","en":"A merchant is a person who buys or sells goods in large quantities, especially one who imports and exports them.","ex":{"en":"Any knowledgeable wine merchant would be able to advise you.","cn":"任何一个懂行的葡萄酒商人都可以给你提出建议。"}},{"pos":"N-COUNT 可数名词","cn":"店主;商人","en":"A merchant is a person who owns or runs a shop, store, or other business.","ex":{"en":"The family was forced to live on credit from local merchants.","cn":"这家人不得不靠向当地商人赊账生活。"}},{"pos":"ADJ 形容词","cn":"海上货运的;商船的","en":"Merchant seamen or ships are involved in carrying goods for trade.","ex":{"en":"There's been a big reduction in the size of the British merchant fleet in recent years.","cn":"近些年来英国商船队伍的规模大为缩减。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company or person that sells goods to the public in a shop - used especially in business contexts","cn":""},{"en":"a person or company that sells goods in large quantities and at low prices, especially to other companies that then sell the goods to the public","cn":""},{"en":"a person or company that buys and sells large quantities of goods such as wine, or basic materials such as coal and wood","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A merchant is someone who works in or owns a retail business and sells goods. In Paris you can stroll from merchant to merchant , buying a loaf of bread in one shop and a wedge of cheese in another."}]},"collocations":{"phrases":["ADJ. prosperous, rich, wealthy | powerful, prominent, substantial, successful | foreign, local | builders', coal, corn, timber, wine, wool W","MERCHANT + NOUN fleet, marine, seaman, ship, shipping, vessel"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdemerchant.mp3","us":"media/ldoce/hwd/ame/3/merchant.mp3"},"examples":[{"en":"Venice was once a city of rich merchants.","cn":"威尼斯曾是富商云集的城市。"},{"en":"a speed merchant (= sb who likes to drive fast)","cn":"好开快车的人"}],"oxford":{"phon":"ˈmɜːtʃənt","pos":"noun","senses":[{"en":"a person who buys and sells goods in large quantities, especially one who imports and exports goods","cn":"批发商；（尤指）进出口批发商","ex":{"en":"a coal/wine merchant","cn":"煤炭／葡萄酒批发商"}},{"en":"a person who sells goods to the public, especially through a store","cn":"商人；商家","lab":"North American English","ex":{"en":"The credit cards are accepted by 10 million merchants worldwide.","cn":"信用卡被全球 1 000 万商家接受。"}},{"en":"a person who likes a particular activity","cn":"（某活动的）爱好者；热衷于…的人","lab":"British English, informal, disapproving，，，，","ex":{"en":"a speed merchant (= somebody who likes to drive fast)","cn":"好开快车的人"}},{"en":"connected with the transport of goods by sea","cn":"海上货运的","ex":{"en":"merchant seamen","cn":"商船船员"},"pos":"adjective"}]}},"memorial":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纪念碑","en":"A memorial is a structure built in order to remind people of a famous person or event.","ex":{"en":"Building a memorial to Columbus has been his lifelong dream","cn":"为哥伦布建一座纪念碑是他一生的梦想。"}},{"pos":"ADJ 形容词","cn":"（对逝者）纪念的;悼念的;追思的","en":"A memorial event, object, or prize is in honour of someone who has died, so that they will be remembered.","ex":{"en":"A memorial service is being held for her at St Paul's Church.","cn":"她的追悼会正在圣保罗教堂举行。"}},{"pos":"N-COUNT 可数名词","cn":"（追忆逝者的）纪念物,纪念品","en":"If you say that something will be a memorial to someone who has died, you mean that it will continue to exist and remind people of them.","ex":{"en":"The museum will serve as a memorial to the millions who passed through Ellis Island","cn":"这个博物馆将用来纪念经过埃利斯岛的数百万移民。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something, especially a stone with writing on it, that reminds people of someone who has died","cn":"纪念物﹐〔尤指〕纪念碑"},{"en":"an achievement that reminds people of someone who has died 〔","cn":"使人想起死者成就的〕纪念物﹐纪念"},{"en":"if something is done in memory of someone who has died, it is done so that the person is not forgotten, and to show respect for them","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Just as the Lincoln Memorial pays tribute to Abraham Lincoln, a memorial is anything that symbolizes or celebrates someone who died. Every gravestone in a cemetery is actually a small memorial ."}]},"collocations":{"phrases":["ADJ. lasting, permanent The statue is a lasting memorial to those who died in the war. | fitting | war","VERB + MEMORIAL build, erect, put up | unveil","MEMORIAL + VERB commemorate sb/sth | stand The memorial stands on the village green.","MEMORIAL + NOUN ceremony, service a memorial service for sailors drowned at sea","PREP. ~ for a memorial for victims of the air crash | ~ to The prime minister today unveiled a memorial to those who died in the disaster."]},"media":{"uk":"media/ldoce/hwd/bre/5/memorial_adj0205.mp3","us":"media/ldoce/hwd/ame/d/memorial.mp3"},"examples":[{"en":"The painting will be a lasting memorial to a remarkable woman.","cn":"这幅油画将成为对一位杰出女性的永久纪念。"},{"en":"The memorial service will be held at a local church.","cn":"悼念仪式将在当地的一所教堂举行。"}],"oxford":{"phon":"məˈmɔːriəl","pos":"noun","senses":[{"en":"a statue, stone, etc. that is built in order to remind people of an important past event or of a famous person who has died","cn":"纪念碑（或像等）","g":"[countable]","ex":{"en":"a war memorial (= in memory of soldiers who died in a war)","cn":"阵亡将士纪念碑"}},{"en":"a thing that will continue to remind people of somebody/something","cn":"纪念物；纪念品","g":"[singular]","ex":{"en":"The painting will be a lasting memorial to a remarkable woman.","cn":"这幅油画将成为对一位杰出女性的永久纪念。"}},{"en":"a ceremony that is held to remember somebody who has died or an important past event","cn":"纪念仪式；纪念会","g":"[countable]","ex":{"en":"a memorial for victims of the air crash","cn":"为空难罹难者建造的纪念碑"}},{"en":"created or done in order to remember somebody who has died","cn":"纪念的；悼念的","ex":{"en":"a memorial statue/plaque/prize","cn":"纪念像／牌／奖"},"pos":"adjective"}]}},"medal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"奖章;勋章；奖牌","en":"A medal is a small metal disc which is given as an award for bravery or as a prize in a sporting event."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is given to the person who wins a competition, game, or race","cn":""},{"en":"a special silver or gold container, shaped like a large cup with two handles, that is given to the winner of a sports competition","cn":""},{"en":"a round flat piece of metal that is given to someone who has won a race, game, or competition","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A medal is an award for some contest or achievement. You might win a medal for coming in third place at the cupcake baking championship."}]},"collocations":{"phrases":["ADJ. bronze, gold, silver He won a gold medal in the 100 metres. | championship, Olympic | commemorative A commemorative medal was struck in","VERB + MEDAL be awarded, collect, get, receive, win | award (sb), give sb, present (sb with) | strike","MEDAL + NOUN winner | hope, hopes He is a major medal hope for Britain. Her medal hopes were dashed by injury.","PREP. ~ for a medal for bravery"]},"media":{"img":["media/ldoce/img/medal.jpg","media/pic/medal_comp.jpg"],"uk":"media/ldoce/hwd/bre/9/medal_n0205.mp3","us":"media/ldoce/hwd/ame/8/medal.mp3"},"examples":[{"en":"Evans has medalled at several international events.","cn":"埃文斯已经多次在国际比赛中获奖。"},{"en":"to win a gold medal in the Olympics","cn":"在奥林匹克运动会上赢得一枚金牌"}],"oxford":{"phon":"ˈmedl","pos":"noun","senses":[{"en":"a flat piece of metal, usually like a coin in shape, that is given to the winner of a competition or to somebody who has been brave, for example in war","cn":"奖章；勋章","ex":{"en":"to win a gold medal in the Olympics","cn":"在奥林匹克运动会上赢得一枚金牌"}},{"en":"to win a medal in a competition","cn":"（在比赛中）获得奖牌（或奖章）","ex":{"en":"Evans has medalled at several international events.","cn":"埃文斯已经数次在国际比赛中获奖。"},"pos":"verb"}]}},"metre":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"米","en":"A metre is a metric unit of length equal to 100 centimetres.","ex":{"en":"Chris Boardman won the Olympic 4,000 metres pursuit","cn":"克里斯·博德曼赢得了奥运会4,000米自行车追逐赛的冠军。"}},{"pos":"N-VAR 可变名词","cn":"(诗歌的)韵律，格律","en":"In the study of poetry, metre is the regular and rhythmic arrangement of syllables according to particular patterns.","ex":{"en":"They must each compose a poem in strict alliterative metre","cn":"他们必须每人作一首严格押头韵的诗。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the basic unit for measuring length in the metric system","cn":"米﹐公尺"},{"en":"the arrangement of sounds in poetry into patterns of strong and weak beats 〔","cn":"诗的〕格律﹐韵律"}]},"media":{"uk":"media/ldoce/hwd/bre/e/metre0205.mp3","us":"media/ldoce/hwd/ame/8/laadmetre.mp3"},"examples":[{"en":"She came second in the 200 metres.","cn":"在 200 米比赛中，她取得了第二名。"},{"en":"the 4×100 metre(s) relay * 4×100","cn":"米接力赛"}],"oxford":{"phon":"ˈmiːtə(r)","pos":"noun","senses":[{"en":"a unit for measuring length; a hundred centimetres","cn":"米；公尺","g":"[countable]","ex":{"en":"a 50-metre swimming pool","cn":"50 米泳池"}},{"en":"used in the name of races","cn":"用于竞赛名称","g":"[countable, uncountable]","ex":{"en":"She came second in the 200 metres.","cn":"在 200 米比赛中，她取得了第二名。"}},{"en":"the arrangement of strong and weak stresses in lines of poetry that produces the rhythm; a particular example of this","cn":"（诗的）格律","g":"[uncountable, countable]","ex":{"en":"She knows a lot about verse metre.","cn":"她很懂诗律。"}}]}},"menopause":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"更年期，绝经期(通常在50岁左右)","en":"The menopause is the time during which a woman gradually stops menstruating, usually when she is about fifty years old."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the time when a woman stops menstruat ing , which usually happens around the age of 50 〔","cn":"妇女的〕绝经期﹐更年期"}]},"collocations":{"phrases":["ADJ. early | male The male menopause is said to affect men who are approaching middle age.","VERB + MENOPAUSE reach | go through","PREP. at the ~, after/past the ~ a disease that can afflict women past the menopause | during the ~"]},"media":{"uk":"media/ldoce/hwd/bre/3/menopause0205.mp3","us":"media/ldoce/hwd/ame/e/menopause.mp3"},"examples":[{"en":"menopausal women/symptoms","cn":"更年期的妇女/症状"},{"en":"to reach (the) menopause","cn":"到更年期"}],"oxford":{"phon":"ˈmenəpɔːz","pos":"noun","senses":[{"en":"the time during which a woman gradually stops menstruating, usually at around the age of 50","cn":"绝经期；（妇女的）更年期","ex":{"en":"to reach (the) menopause","cn":"到更年期"}}]}},"menacing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"威胁的;威吓的;危险的","en":"If someone or something looks menacing, they give you a feeling that they are likely to cause you harm or put you in danger.","ex":{"en":"The strong dark eyebrows give his face an oddly menacing look","cn":"两道浓黑的眉毛使他的脸看起来异常凶狠。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel frightened","cn":""},{"en":"frightening. Scary is less formal than frightening and is very common in everyday English","cn":""},{"en":"frightening, especially because violence, cruelty, or danger is involved","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is menacing is threatening or suggestive of coming danger. If you’re backing away slowly from something, you can probably use the adjective menacing to describe it!"}]},"collocations":{"phrases":["VERBS appear, be, look, seem | become","ADV. almost His voice was quiet and almost menacing. | faintly, rather, slightly She had a slightly menacing manner. | darkly darkly menacin"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdemenacing.mp3","us":"media/ldoce/hwd/ame/9/laadmenacing.mp3"},"examples":[{"en":"At night, the dark streets become menacing.","cn":"在夜晚，漆黑的街道变得阴森森的。"},{"en":"The thunder growled menacingly.","cn":"雷声轰鸣，叫人害怕。"}],"oxford":{"phon":"ˈmenəsɪŋ","pos":"adjective","senses":[{"en":"seeming likely to cause you harm or danger","cn":"威胁的；恐吓的；危险的","ex":{"en":"a menacing face/tone","cn":"恶狠脸色／口吻"}}]}},"memo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(公司或组织内部的)公务便条，备忘录","en":"A memo is a short official note that is sent by one person to another within the same company or organization."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a written or printed message that is usually put in an envelope and sent by mail","cn":""},{"en":"letters, papers, parcels etc that are sent and delivered using the postal system","cn":""},{"en":"a short informal letter written from one person to another","cn":""}]},"collocations":{"phrases":["ADJ. internal","QUANT. copy","VERB + MEMO draft, write | circulate, send (out) | receive | sign | leak","MEMO + NOUN pad","PREP. in a/the ~ | ~ from, ~ of my memo of 28 June, 2001 | ~ on A memo on the curriculum changes from the Head of Education. | ~ to She ciur"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdememo.mp3","us":"media/ldoce/hwd/ame/f/memo.mp3"},"examples":[{"en":"to write/send/circulate a memo","cn":"写/发送/传阅备忘录"},{"en":"I sent him a memo reminding him about the meeting.","cn":"我发给他一个通知﹐提醒他开会的事。"}],"oxford":{"phon":"ˈmeməʊ","pos":"noun","senses":[{"en":"an official note from one person to another in the same organization","cn":"备忘录","ex":{"en":"to write/send a memo","cn":"写／发送备忘录"}}]}},"meningitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"脑（脊）膜炎","en":"Meningitis is a serious infectious illness which affects your brain and spinal cord."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious illness in which the outer part of the brain becomes swollen","cn":"脑（脊）膜炎"}]},"collocations":{"phrases":["ADJ. acute | bacterial, meningococcal, viral","QUANT. case","VERB + MENINGITIS have, suffer from He is suffering from viral meningitis. | catch, contract •"]},"media":{"uk":"media/ldoce/hwd/bre/3/meningitis0205.mp3","us":"media/ldoce/hwd/ame/d/meningitis.mp3"},"oxford":{"phon":"ˌmenɪnˈdʒaɪtɪs","pos":"noun","senses":[{"en":"a serious disease in which the membranes surrounding the brain and spinal cord develop an infection and become swollen (= larger than normal), causing severe headache, a high temperature and sometimes death","cn":"脑膜炎；脑脊膜炎","ex":{"en":"He is suffering from viral meningitis.","cn":"他患有病毒性脑膜炎。"}}]}},"melbourne":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the second largest city in Australia, which is the capital of the state of Victoria in the southeast of the country. It is an important business, industrial, and cultural centre.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/p028-000008138.mp3","us":"media/ldoce/hwd/ame/5/p028-000008138.mp3"},"oxford":{"phon":"ˈmelbən","pos":"","senses":[{"en":"the capital of the state of Victoria, in south-eastern Australia, on the Bass Strait opposite Tasmania. It became state capital in 1851 and was capital of Australia from 1901 until 1927. It is a major port and the second-largest city in Australia.","cn":"墨尔本（澳大利亚东南部维多利亚州首府，隔巴斯海峡与塔斯马尼亚岛相望。在 1851 年成为州首府，从 1901 年到 1927 年是澳大利亚首都。为主要港口和澳大利亚第二大城市）"}]}},"meaningless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（指话语、所写内容）意思不明确的，无法理解的，没有意义的","en":"If something that someone says or writes is meaningless, it has no meaning, or appears to have no meaning.","ex":{"en":"The sentence 'kicked the ball the man' is meaningless","cn":"kicked the ball the man 这句话毫无意义。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不重要的;不相关的","en":"Something that is meaningless in a particular situation is not important or relevant.","ex":{"en":"Widespread political and economic disarray threatens to make the constitution meaningless","cn":"四处蔓延的政治和经济混乱可能会使宪法变得可有可无。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无目的的;无价值的","en":"If something that you do is meaningless, it has no purpose and is not at all worthwhile.","ex":{"en":"They seek strong sensations to dull their sense of a meaningless existence.","cn":"为了冲淡生活毫无意义的感觉，他们追求强烈的刺激。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is meaningless has no meaning, and is therefore useless, wrong, or stupid","cn":""},{"en":"speech or writing that has no meaning","cn":""},{"en":"complicated language, especially in an official document, that seems to have no meaning","cn":""}]},"collocations":{"phrases":["VERBS be | become | render sth","ADV. absolutely, quite, totally | increasingly | almost, practically, virtually The phrase has become almost meaningless. | essentially, lar"]},"media":{"uk":"media/ldoce/hwd/bre/4/meaningless0205.mp3","us":"media/ldoce/hwd/ame/1/meaningless.mp3"},"examples":[{"en":"Fines are meaningless to a huge company like that.","cn":"对于这样一家大公司，罚金根本算不了什么。"},{"en":"We fill up our lives with meaningless tasks.","cn":"我们终日忙忙碌碌，过得毫无意义。"}],"oxford":{"phon":"ˈmiːnɪŋləs","pos":"adjective","senses":[{"en":"without any purpose or reason and therefore not worth doing or having","cn":"毫无意义的；毫无目的的；无价值的","ex":{"en":"a meaningless existence","cn":"毫无意义的存在"}},{"en":"not considered important","cn":"不重要的；无所谓的","ex":{"en":"Fines are meaningless to a huge company like that.","cn":"对于这样一家大公司，罚金根本算不了什么。"}},{"en":"not having a meaning that is easy to understand","cn":"意思不明确的；晦涩的","ex":{"en":"To me that painting is completely meaningless.","cn":"对我来说，这幅油画晦涩难懂。"}}]}},"merchandise":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"商品;货物","en":"Merchandise is goods that are bought, sold, or traded."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is made or produced in large quantities, usually in order to be sold","cn":""},{"en":"things that are produced in order to be sold, especially for use in the home","cn":""},{"en":"a type of product or raw material that can be bought and sold – used especially about basic food products, metals, and fuels","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"The noun merchandise refers to things that can be bought or sold, like the merchandise that's for sale at your local record shop, or the merchandise sold by sidewalk vendors in a big city."}]},"collocations":{"phrases":["ADJ. general","QUANT. piece a substandard piece of merchandise","VERB + MERCHANDISE buy, purchase | carry, sell The company carries a wide range of merchandise.","PHRASES a range of merchandise"]},"media":{"uk":"media/ldoce/hwd/bre/e/merchandise_n0205.mp3","us":"media/ldoce/hwd/ame/2/merchandise1.mp3"},"examples":[{"en":"official Olympic merchandise","cn":"奥林匹克运动会官方指定商品"},{"en":"a wide selection of merchandise","cn":"品种丰富的商品"}],"oxford":{"phon":"ˈmɜːtʃəndaɪs","pos":"noun","senses":[{"en":"goods that are bought or sold; goods that are for sale in a shop","cn":"商品；货品","lab":"formal","ex":{"en":"a wide selection of merchandise","cn":"品种丰富的商品"}},{"en":"things you can buy that are connected with or that advertise a particular event or organization","cn":"相关商品；指定商品","ex":{"en":"official Olympic merchandise","cn":"奥林匹克运动会官方指定商品"}},{"en":"to sell something using advertising, etc.","cn":"推销；（运用广告等进行）销售","ex":{"en":"She works with companies that want to make or merchandise products related to the company’s films.","cn":"她与想为自家电影制作或推销衍生产品的公司打交道。"},"pos":"verb"}]}},"merger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(公司、组织等的)合并，归并","en":"A merger is the joining together of two separate companies or organizations so that they become one.","ex":{"en":"...a merger between two of Britain's biggest trades unions.","cn":"英国两个最大的工会的合并"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the joining together of two or more companies or organizations to form one larger one 〔","cn":"公司﹑组织的〕合并"}]},"vocab":{"pos":"n","senses":[{"en":"When two companies become one company, they've had a merger . A merger is like a marriage for things other than people."}]},"collocations":{"phrases":["ADJ. proposed","VERB + MERGER plan | agree | carry out","MERGER + VERB go through If the merger goes through, thousands of jobs will be lost.","MERGER + NOUN activity | proposal | negotiations | agreement","PREP. ~ between the merger between Lake Biscuits and D M Confectionery"]},"media":{"uk":"media/ldoce/hwd/bre/5/merger0205.mp3","us":"media/ldoce/hwd/ame/a/merger.mp3"},"examples":[{"en":"our proposed merger with the university","cn":"我们与这所大学提议中的合并"},{"en":"a merger between the two banks","cn":"两家银行的合并"}],"oxford":{"phon":"ˈmɜːdʒə(r)","pos":"noun","senses":[{"en":"the act of joining two or more organizations or businesses into one","cn":"（机构或企业的）合并，归并","lab":"North American English","ex":{"en":"If the merger goes through, thousands of jobs will be lost.","cn":"如果合并得以完成，将会失去数千工作岗位。"}}]}}});
